"""Builds a routable graph from the RFN line shapes and snaps stations onto it.

All coordinates are Lambert-93 metres (EPSG:2154).
"""
import numpy as np
from shapely.geometry import LineString, Point
from shapely.strtree import STRtree
from scipy.spatial import cKDTree

CLUSTER_TOL = 20.0      # endpoints closer than this are the same junction
T_TOL_SNAPPED = 3.0     # endpoint lying this close to another line's body is a T-junction
T_TOL_DANGLING = 40.0   # a dangling endpoint is pulled onto another line within this distance
STATION_RADIUS = 400.0  # max distance between a station and the line it is attached to
STATION_NODE_TOL = 12.0 # reuse an existing junction if the station is this close to it


def rnd(p):
    return (round(float(p[0]), 2), round(float(p[1]), 2))


def _insert_points(xy, inserts, new_start, new_end):
    """Insert points (list of (x,y)) into polyline xy, replacing the end vertices."""
    xy = xy.copy()
    xy[0] = new_start
    xy[-1] = new_end
    if not inserts:
        return xy
    seg = np.diff(xy, axis=0)
    seglen = np.hypot(seg[:, 0], seg[:, 1])
    cum = np.concatenate([[0.0], np.cumsum(seglen)])
    line = LineString(xy)
    items = []
    for p in inserts:
        d = line.project(Point(p))
        k = int(np.searchsorted(cum, d, side='right') - 1)
        k = max(0, min(k, len(xy) - 2))
        items.append((d, k, p))
    items.sort(key=lambda t: t[0])
    out = []
    ii = 0
    for k in range(len(xy)):
        out.append(tuple(xy[k]))
        while ii < len(items) and items[ii][1] == k:
            p = items[ii][2]
            if np.hypot(p[0] - out[-1][0], p[1] - out[-1][1]) > 0.005:
                out.append(tuple(p))
            ii += 1
    return np.array(out)


class Graph:
    pass


def build(lines, log=print):
    """lines: list of dict(code=str, xy=np.ndarray(N,2)). Returns (lines_final, special_on, node_index)."""
    n = len(lines)
    pts = np.array([[l['xy'][0], l['xy'][-1]] for l in lines]).reshape(-1, 2)
    kd = cKDTree(pts)
    parent = list(range(len(pts)))

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a
    for a, b in kd.query_pairs(CLUSTER_TOL):
        if a // 2 == b // 2:
            continue
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    clusters = {}
    for k in range(len(pts)):
        clusters.setdefault(find(k), []).append(k)
    canon = {}
    for r, mem in clusters.items():
        c = pts[mem].mean(axis=0) if len(mem) > 1 else pts[mem[0]]
        for k in mem:
            canon[k] = rnd(c)
    geoms = [LineString(l['xy']) for l in lines]
    tree = STRtree(geoms)
    inserts = [[] for _ in range(n)]
    stats = dict(T_exact=0, T_pulled=0, dangling=0)
    for r, mem in clusters.items():
        c = np.array(canon[mem[0]])
        members = {k // 2 for k in mem}
        cp = Point(c)
        best, bj = 1e18, -1
        for j in tree.query(cp.buffer(T_TOL_DANGLING)):
            if j in members:
                continue
            d = geoms[j].distance(cp)
            if d < best:
                best, bj = d, j
        snap = None
        if bj >= 0 and (best <= T_TOL_SNAPPED or (len(mem) == 1 and best <= T_TOL_DANGLING)):
            g = geoms[bj]
            P = g.interpolate(g.project(cp))
            P = rnd((P.x, P.y))
            # close to an endpoint of the other line -> reuse that endpoint's junction
            for side in (0, 1):
                e = canon[2 * bj + side]
                if np.hypot(P[0] - e[0], P[1] - e[1]) < 5.0:
                    P = e
                    break
            else:
                inserts[bj].append(P)
            snap = P
            stats['T_exact' if best <= T_TOL_SNAPPED else 'T_pulled'] += 1
        elif len(mem) == 1:
            stats['dangling'] += 1
        if snap is not None:
            for k in mem:
                canon[k] = snap
    log('noding:', stats, 'clusters', len(clusters))
    out = []
    special_on = []
    for i, l in enumerate(lines):
        xy = _insert_points(l['xy'], inserts[i], canon[2 * i], canon[2 * i + 1])
        out.append(dict(code=l['code'], xy=xy, meta=l.get('meta')))
        special_on.append([canon[2 * i], canon[2 * i + 1]] + list(inserts[i]))
    return out, special_on


def snap_stations(lines, special_on, stations, log=print):
    """stations: list of dict(x,y,codes:set). Adds 'snap' (x,y) / 'sdist' / 'line' keys. Returns updated lines."""
    geoms = [LineString(l['xy']) for l in lines]
    tree = STRtree(geoms)
    by_code = {}
    for i, l in enumerate(lines):
        by_code.setdefault(l['code'], []).append(i)
    ins = [[] for _ in lines]
    ok = 0
    for s in stations:
        p = Point(s['x'], s['y'])
        cand = tree.query(p.buffer(STATION_RADIUS))
        if len(cand) == 0:
            s['snap'] = None
            continue
        pref = [j for j in cand if lines[j]['code'] in s['codes']]
        pool = pref if pref else list(cand)
        j = min(pool, key=lambda jj: geoms[jj].distance(p))
        d = geoms[j].distance(p)
        # a station declared on line X but much farther than some other line: trust geometry
        if pref:
            dall = min(geoms[jj].distance(p) for jj in cand)
            if d > dall + 150:
                j = min(cand, key=lambda jj: geoms[jj].distance(p))
                d = geoms[j].distance(p)
        P = geoms[j].interpolate(geoms[j].project(p))
        P = rnd((P.x, P.y))
        for sp in special_on[j]:
            if np.hypot(P[0] - sp[0], P[1] - sp[1]) <= STATION_NODE_TOL:
                P = sp
                break
        else:
            ins[j].append(P)
            special_on[j].append(P)
        s['snap'] = P
        s['sdist'] = d
        s['line'] = j
        ok += 1
    log('stations snapped', ok, 'of', len(stations))
    out = []
    for i, l in enumerate(lines):
        if ins[i]:
            xy = _insert_points(l['xy'], ins[i], l['xy'][0], l['xy'][-1])
        else:
            xy = l['xy']
        out.append(dict(code=l['code'], xy=xy, meta=l.get('meta')))
    return out, special_on


def make_graph(lines, special_on):
    """Split lines at special vertices into edges. Returns Graph."""
    node_id = {}
    node_xy = []
    for sp in special_on:
        for p in sp:
            if p not in node_id:
                node_id[p] = len(node_xy)
                node_xy.append(p)
    edges = []
    for li, l in enumerate(lines):
        xy = l['xy']
        idx = [k for k in range(len(xy)) if rnd(xy[k]) in node_id]
        if 0 not in idx:
            idx.insert(0, 0)
        if len(xy) - 1 not in idx:
            idx.append(len(xy) - 1)
        for a, b in zip(idx[:-1], idx[1:]):
            seg = xy[a:b + 1]
            if len(seg) < 2:
                continue
            u = node_id.get(rnd(seg[0]))
            v = node_id.get(rnd(seg[-1]))
            if u is None or v is None or u == v:
                continue
            ln = float(np.hypot(*np.diff(seg, axis=0).T).sum())
            if ln < 0.5:
                continue
            edges.append(dict(u=u, v=v, xy=seg, len=ln, line=li))
    g = Graph()
    g.node_xy = np.array(node_xy)
    g.edges = edges
    g.node_id = node_id
    return g

