// Canvas renderer: a static-ish "base" layer (map, network, stations, labels) and a per-frame "dynamic" layer (trains, selection).
import { CATS, BANDS, bandOf, clamp, ramp, rgba, mix, durShort } from './util.js';
import { getLeg, trainState, pointOnLeg } from './data.js';

const FLOW_LEVELS = 16;
const ALL_RAMP = [[0, [44, 58, 150]], [0.22, [112, 56, 190]], [0.45, [214, 58, 138]], [0.7, [255, 142, 48]], [1, [255, 244, 196]]];
const TRAIN_SIZE = [3.3, 2.5, 1.7];
const TRAIL_PX = [30, 20, 13];

const CITIES = [
  // [label, station name, tier]
  ['Paris', 'Paris Gare du Nord', 1], ['Lyon', 'Lyon Part Dieu', 1], ['Marseille', 'Marseille Saint-Charles', 1],
  ['Lille', 'Lille Flandres', 1], ['Bordeaux', 'Bordeaux Saint-Jean', 1], ['Toulouse', 'Toulouse Matabiau', 1],
  ['Nantes', 'Nantes', 1], ['Strasbourg', 'Strasbourg', 1], ['Nice', 'Nice', 1], ['Rennes', 'Rennes', 1],
  ['Montpellier', 'Montpellier Saint-Roch', 1], ['Bruxelles', 'Bruxelles Midi', 1], ['Genève', 'Genève Cornavin', 1],
  ['Barcelona', 'Barcelone-Sants', 1], ['Luxembourg', 'Luxembourg', 2],
  ['Dijon', 'Dijon', 2], ['Grenoble', 'Grenoble', 2], ['Metz', 'Metz', 2], ['Brest', 'Brest', 2],
  ['Clermont-Ferrand', 'Clermont-Ferrand', 2], ['Limoges', 'Limoges Bénédictins', 2], ['Tours', 'Tours', 2],
  ['Reims', 'Reims', 2], ['Rouen', 'Rouen Rive Droite', 2], ['Le Havre', 'Le Havre', 2], ['Orléans', 'Orléans', 2],
  ['Amiens', 'Amiens', 2], ['Caen', 'Caen', 2], ['Perpignan', 'Perpignan', 2], ['Besançon', 'Besançon Viotte', 2],
  ['Mulhouse', 'Mulhouse', 2], ['Poitiers', 'Poitiers', 2], ['Angers', 'Angers Saint-Laud', 2], ['Le Mans', 'Le Mans', 2],
  ['Nancy', 'Nancy', 2], ['Toulon', 'Toulon', 2], ['Avignon', 'Avignon Centre', 2], ['Saint-Étienne', 'Saint-Étienne Châteaucreux', 2],
  ['Bayonne', 'Bayonne', 2], ['Lausanne', 'Lausanne', 2], ['Stuttgart', 'Stuttgart Hbf', 2], ['Torino', 'Turin Porta Susa', 2],
  ['Frankfurt', 'Francfort sur le Main', 2], ['Basel', 'Basel SBB', 2], ['Quimper', 'Quimper', 3], ['Chambéry', 'Chambéry - Challes-les-Eaux', 3],
  ['Pau', 'Pau', 3], ['Brive', 'Brive-la-Gaillarde', 3], ['Nîmes', 'Nîmes', 3], ['Valence', 'Valence', 3], ['La Rochelle', 'La Rochelle', 3],
  ['Troyes', 'Troyes', 3], ['Cherbourg', 'Cherbourg-en-Cotentin', 3], ['Dunkerque', 'Dunkerque', 3], ['Biarritz', 'Biarritz', 3],
  ['Annecy', 'Annecy', 3], ['Albi', 'Albi', 3], ['Rodez', 'Rodez', 3], ['Carcassonne', 'Carcassonne', 3], ['Calais', 'Calais', 3],
  ['Vannes', 'Vannes', 3], ['Saint-Malo', 'Saint-Malo', 3], ['Colmar', 'Colmar', 3], ['Belfort', 'Belfort', 3], ['Cannes', 'Cannes', 3],
];

export class Renderer {
  constructor(M, baseCanvas, dynCanvas, cam) {
    this.M = M; this.cam = cam;
    this.bc = baseCanvas; this.dc = dynCanvas;
    this.b = baseCanvas.getContext('2d');
    this.d = dynCanvas.getContext('2d');
    this.dpr = 1;
    this.D = null;
    this.legPaths = new Map();
    this.flow = null;
    this.tree = null;
    this.drawn = { n: 0, x: new Float32Array(8192), y: new Float32Array(8192), t: new Int32Array(8192) };
    this._st = {};
    this._pt = { x: 0, y: 0 };

    // static edge paths
    this.allEdgesPath = this._pathOf(M.edges.xy.map((_, i) => i));
    // city anchors
    const byName = new Map();
    M.st.name.forEach((n, i) => { if (!byName.has(n)) byName.set(n, i); });
    this.cities = CITIES.map(([label, sn, tier]) => ({ label, tier, s: byName.get(sn) })).filter((c) => c.s != null);
    this.sprites = CATS.map((c) => this._sprite(c.rgb));
    this.bounds = null;
  }

  resize(W, H, dpr) {
    this.dpr = dpr;
    for (const c of [this.bc, this.dc]) { c.width = Math.round(W * dpr); c.height = Math.round(H * dpr); c.style.width = W + 'px'; c.style.height = H + 'px'; }
  }

  setDay(D) {
    this.D = D;
    const M = this.M;
    // station importance ranking
    const n = M.st.n;
    const idx = Array.from({ length: n }, (_, i) => i).sort((a, b) => D.callsTotal[b] - D.callsTotal[a]);
    this.rank = new Int32Array(n);
    idx.forEach((s, r) => { this.rank[s] = r; });
    this.maxCalls = Math.max(1, D.callsTotal[idx[0]]);
    this.legPaths.clear();
  }

  _pathOf(list) {
    const p = new Path2D();
    const E = this.M.edges.xy;
    for (const e of list) {
      const xy = E[e];
      p.moveTo(xy[0], xy[1]);
      for (let k = 2; k < xy.length; k += 2) p.lineTo(xy[k], xy[k + 1]);
    }
    return p;
  }
  pathOfCode(code) { return this._pathOf(this.M.edgesOfCode[code]); }

  legPath(id) {
    let p = this.legPaths.get(id);
    if (p) return p;
    const g = getLeg(this.M, id);
    p = new Path2D();
    p.moveTo(g.xy[0], g.xy[1]);
    for (let k = 2; k < g.xy.length; k += 2) p.lineTo(g.xy[k], g.xy[k + 1]);
    this.legPaths.set(id, p);
    return p;
  }

  _sprite(rgb) {
    const s = 64, c = document.createElement('canvas');
    c.width = c.height = s;
    const g = c.getContext('2d');
    const gr = g.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
    gr.addColorStop(0, rgba(rgb, 1));
    gr.addColorStop(0.18, rgba(rgb, 0.75));
    gr.addColorStop(0.45, rgba(rgb, 0.22));
    gr.addColorStop(1, rgba(rgb, 0));
    g.fillStyle = gr; g.fillRect(0, 0, s, s);
    return c;
  }

  /** (re)build the traffic-volume buckets of the flow view. `counts` is [Int32Array x3], `enabled` flags. */
  setFlow(counts, enabled) {
    const M = this.M, ne = M.edges.n;
    const val = new Int32Array(ne);
    let nEn = 0, only = -1;
    for (let c = 0; c < 3; c++) if (enabled[c]) { nEn++; only = c; }
    for (let c = 0; c < 3; c++) if (enabled[c]) for (let e = 0; e < ne; e++) val[e] += counts[c][e];
    let max = 1;
    for (let e = 0; e < ne; e++) if (val[e] > max) max = val[e];
    const buckets = Array.from({ length: FLOW_LEVELS }, () => []);
    const idle = [];
    for (let e = 0; e < ne; e++) {
      if (val[e] <= 0) { idle.push(e); continue; }
      const q = Math.sqrt(val[e] / max);
      buckets[Math.min(FLOW_LEVELS - 1, Math.floor(q * FLOW_LEVELS))].push(e);
    }
    let stops = ALL_RAMP;
    if (nEn === 1) {
      const rgb = CATS[only].rgb;
      stops = [[0, mix(rgb, [0, 0, 0], 0.7)], [0.55, rgb], [1, mix(rgb, [255, 255, 255], 0.88)]];
    }
    this.flow = {
      val, max, idle: this._pathOf(idle),
      levels: buckets.map((l, i) => ({ path: this._pathOf(l), q: (i + 0.5) / FLOW_LEVELS, n: l.length, rgb: ramp(stops, (i + 0.5) / FLOW_LEVELS) })),
      stops,
    };
  }

  /** Build the shortest-travel-time tree of the accessibility mode from a Router result. */
  setAccess(router) {
    const { M, D } = this;
    const paths = BANDS.map(() => new Path2D());
    const c = D.conns;
    const cls = new Int8Array(M.st.n).fill(-1);
    for (let s = 0; s < M.st.n; s++) {
      const t = router.earliest[s] - router.T;
      if (!(t < Infinity) || s === router.origin) continue;
      const b = bandOf(t);
      cls[s] = b;
      const ci = router.via[s];
      if (ci >= 0) {
        const trip = D.trips[c.trip[ci]];
        paths[b].addPath(this.legPath(trip.legs[c.idx[ci]]));
      } else if (router.walkFrom[s] >= 0) {
        const f = router.walkFrom[s];
        const p = new Path2D(); p.moveTo(M.st.x[f], M.st.y[f]); p.lineTo(M.st.x[s], M.st.y[s]);
        paths[b].addPath(p);
      }
    }
    this.tree = { paths, cls, router };
  }

  // ------------------------------------------------------------------ base layer
  _world(ctx) {
    const cam = this.cam, s = cam.scale, d = this.dpr;
    ctx.setTransform(d * s, 0, 0, -d * s, d * (cam.W / 2 + cam.ox - cam.cx * s), d * (cam.H / 2 + cam.oy + cam.cy * s));
  }
  _screen(ctx) { ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0); }

  _stroke(ctx, path, px, style, alpha = 1) {
    ctx.lineWidth = px / this.cam.scale;
    ctx.strokeStyle = style;
    ctx.globalAlpha = alpha;
    ctx.stroke(path);
  }

  drawBase(S) {
    const ctx = this.b, cam = this.cam, M = this.M;
    const zr = cam.scale / cam.fitScale;
    const zf = clamp(Math.pow(zr, 0.32), 1, 2.4);
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;
    ctx.clearRect(0, 0, this.bc.width, this.bc.height);
    ctx.lineJoin = 'round'; ctx.lineCap = 'round';

    // --- graticule (Lambert-93 kilometre grid)
    this._screen(ctx);
    {
      const step = zr > 14 ? 10000 : zr > 4 ? 50000 : 100000;
      ctx.lineWidth = 1;
      const x0 = Math.floor(cam.wx(0) / step) * step, x1 = cam.wx(cam.W);
      const y1 = Math.ceil(cam.wy(0) / step) * step, y0 = cam.wy(cam.H);
      ctx.beginPath();
      for (let x = x0; x <= x1; x += step) { const sx = Math.round(cam.sx(x)) + 0.5; ctx.moveTo(sx, 0); ctx.lineTo(sx, cam.H); }
      for (let y = y0 - ((y0 % step) + step) % step; y <= y1; y += step) { const sy = Math.round(cam.sy(y)) + 0.5; ctx.moveTo(0, sy); ctx.lineTo(cam.W, sy); }
      ctx.strokeStyle = 'rgba(110,150,220,0.045)';
      ctx.stroke();
    }

    // --- land
    this._world(ctx);
    for (const c of M.base.countries) {
      ctx.beginPath();
      for (const poly of c.polys) for (const ring of poly) {
        ctx.moveTo(ring[0], ring[1]);
        for (let k = 2; k < ring.length; k += 2) ctx.lineTo(ring[k], ring[k + 1]);
        ctx.closePath();
      }
      ctx.fillStyle = c.fr ? 'rgba(18,30,52,0.92)' : 'rgba(11,18,31,0.9)';
      ctx.fill('evenodd');
      if (c.fr) {
        ctx.lineWidth = 7 / cam.scale; ctx.strokeStyle = 'rgba(70,120,200,0.07)'; ctx.stroke();
        ctx.lineWidth = 2.6 / cam.scale; ctx.strokeStyle = 'rgba(90,150,240,0.12)'; ctx.stroke();
        ctx.lineWidth = 1 / cam.scale; ctx.strokeStyle = 'rgba(140,185,255,0.42)'; ctx.stroke();
      } else {
        ctx.lineWidth = 0.9 / cam.scale; ctx.strokeStyle = 'rgba(120,150,200,0.2)'; ctx.stroke();
      }
    }
    // --- départements
    ctx.beginPath();
    for (const l of M.base.dep) {
      ctx.moveTo(l[0], l[1]);
      for (let k = 2; k < l.length; k += 2) ctx.lineTo(l[k], l[k + 1]);
    }
    ctx.lineWidth = 0.7 / cam.scale; ctx.strokeStyle = 'rgba(120,160,225,0.11)'; ctx.stroke();

    // --- network
    ctx.globalCompositeOperation = 'lighter';
    const mode = S.mode;
    if (mode === 'flow' && this.flow) this._drawFlow(ctx, zf);
    else this._drawPlainNetwork(ctx, zf, mode === 'access');

    if (mode === 'access' && this.tree) {
      const w = [2.6, 2.2, 1.9, 1.6, 1.4];
      for (let b = BANDS.length - 1; b >= 0; b--) {
        const rgb = hex(BANDS[b].color);
        this._stroke(ctx, this.tree.paths[b], w[b] * zf * 3.4, rgba(rgb, 1), 0.07);
        this._stroke(ctx, this.tree.paths[b], w[b] * zf * 1.6, rgba(rgb, 1), 0.22);
        this._stroke(ctx, this.tree.paths[b], w[b] * zf, rgba(rgb, 1), 0.92);
      }
    }
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';

    // --- stations + labels
    this._screen(ctx);
    this._drawStations(ctx, S, zr, zf);
    this._drawLabels(ctx, S, zr);
  }

  _drawPlainNetwork(ctx, zf, dim) {
    const D = this.D;
    if (!this.plain) this._buildPlain();
    const P = this.plain;
    const k = dim ? 0.55 : 1;
    this._stroke(ctx, P.idle, 0.7 * zf, 'rgba(70,95,140,1)', 0.22 * k);
    this._stroke(ctx, P.used, 4.2 * zf, 'rgba(70,130,230,1)', 0.05 * k);
    this._stroke(ctx, P.used, 1.15 * zf, 'rgba(112,152,222,1)', 0.5 * k);
    this._stroke(ctx, P.lgv, 3.6 * zf, 'rgba(120,150,255,1)', 0.07 * k);
    this._stroke(ctx, P.lgv, 1.5 * zf, 'rgba(172,196,255,1)', 0.62 * k);
  }
  _buildPlain() {
    const M = this.M, D = this.D;
    const used = [], idle = [], lgv = [];
    const tot = D.flowFull;
    for (let e = 0; e < M.edges.n; e++) {
      const v = tot[0][e] + tot[1][e] + tot[2][e];
      if (v <= 0) idle.push(e);
      else if (M.edges.lgv[e]) lgv.push(e);
      else used.push(e);
    }
    this.plain = { idle: this._pathOf(idle), used: this._pathOf(used), lgv: this._pathOf(lgv) };
  }
  invalidatePlain() { this.plain = null; }

  _drawFlow(ctx, zf) {
    const F = this.flow;
    this._stroke(ctx, F.idle, 0.6 * zf, 'rgba(60,82,120,1)', 0.2);
    for (let i = 0; i < F.levels.length; i++) {
      const L = F.levels[i];
      if (!L.n) continue;
      const w = (0.7 + 5.6 * Math.pow(L.q, 1.15)) * zf;
      const col = rgba(L.rgb, 1);
      const lum = 0.35 + 0.65 * L.q;
      this._stroke(ctx, L.path, w * 3.6, col, 0.05 + 0.07 * L.q);
      this._stroke(ctx, L.path, w * 1.7, col, 0.14 + 0.2 * L.q);
      this._stroke(ctx, L.path, w, col, 0.55 + 0.45 * lum);
    }
  }

  _drawStations(ctx, S, zr, zf) {
    const M = this.M, cam = this.cam, D = this.D;
    const mode = S.mode;
    const K = mode === 'access' ? M.st.n : Math.min(M.st.n, Math.floor(18 * Math.pow(zr, 1.9)));
    const W = cam.W, H = cam.H;
    const cls = mode === 'access' && this.tree ? this.tree.cls : null;
    const origin = mode === 'access' && this.tree ? this.tree.router.origin : -1;
    const halo = new Path2D(), core = new Path2D();
    const byBand = BANDS.map(() => ({ core: new Path2D(), halo: new Path2D() }));
    const none = new Path2D();
    for (let s = 0; s < M.st.n; s++) {
      if (this.rank[s] >= K && s !== origin) continue;
      const x = cam.sx(M.st.x[s]), y = cam.sy(M.st.y[s]);
      if (x < -10 || y < -10 || x > W + 10 || y > H + 10) continue;
      const imp = Math.sqrt(D.callsTotal[s] / this.maxCalls);
      if (mode === 'access') {
        const b = cls ? cls[s] : -1;
        const r = (1.35 + 2.6 * imp) * Math.min(zf, 1.8);
        if (b < 0) { none.moveTo(x + r * 0.6, y); none.arc(x, y, r * 0.6, 0, 6.2832); continue; }
        byBand[b].core.moveTo(x + r, y); byBand[b].core.arc(x, y, r, 0, 6.2832);
        if (b <= 2) { byBand[b].halo.moveTo(x + r * 2.6, y); byBand[b].halo.arc(x, y, r * 2.6, 0, 6.2832); }
      } else {
        const r = (0.9 + 2.1 * imp) * Math.min(zf, 1.9);
        core.moveTo(x + r, y); core.arc(x, y, r, 0, 6.2832);
        halo.moveTo(x + r * 2.8, y); halo.arc(x, y, r * 2.8, 0, 6.2832);
      }
    }
    if (mode === 'access') {
      ctx.fillStyle = 'rgba(80,95,120,0.55)'; ctx.fill(none);
      ctx.globalCompositeOperation = 'lighter';
      for (let b = BANDS.length - 1; b >= 0; b--) {
        const rgb = hex(BANDS[b].color);
        ctx.fillStyle = rgba(rgb, 0.14); ctx.fill(byBand[b].halo);
      }
      ctx.globalCompositeOperation = 'source-over';
      for (let b = BANDS.length - 1; b >= 0; b--) {
        ctx.fillStyle = BANDS[b].color; ctx.fill(byBand[b].core);
        ctx.lineWidth = 0.8; ctx.strokeStyle = 'rgba(4,8,14,0.8)'; ctx.stroke(byBand[b].core);
      }
    } else {
      ctx.fillStyle = 'rgba(150,185,255,0.07)'; ctx.fill(halo);
      ctx.fillStyle = 'rgba(214,230,255,0.82)'; ctx.fill(core);
      ctx.lineWidth = 0.7; ctx.strokeStyle = 'rgba(4,8,14,0.7)'; ctx.stroke(core);
    }
  }

  _drawLabels(ctx, S, zr) {
    const M = this.M, cam = this.cam, D = this.D;
    const occ = [];
    const W = cam.W, H = cam.H;
    const fits = (x0, y0, x1, y1) => {
      if (x1 < 0 || y1 < 0 || x0 > W || y0 > H) return false;
      for (const o of occ) if (x0 < o[2] && x1 > o[0] && y0 < o[3] && y1 > o[1]) return false;
      return true;
    };
    ctx.textBaseline = 'middle';
    ctx.lineJoin = 'round';
    // curated city names
    ctx.font = '600 10.5px "Inter", system-ui, -apple-system, "Segoe UI", sans-serif';
    ctx.letterSpacing = '1.6px';
    const maxTier = zr < 1.3 ? 1 : zr < 2.2 ? 2 : 3;
    for (const c of this.cities) {
      if (c.tier > maxTier) continue;
      const x = cam.sx(M.st.x[c.s]), y = cam.sy(M.st.y[c.s]);
      const txt = c.label.toUpperCase();
      const w = ctx.measureText(txt).width;
      const x0 = x + 9, y0 = y - 9;
      if (!fits(x0 - 2, y0 - 7, x0 + w + 2, y0 + 7)) continue;
      occ.push([x0 - 2, y0 - 7, x0 + w + 2, y0 + 7]);
      ctx.lineWidth = 3.5; ctx.strokeStyle = 'rgba(5,9,16,0.85)'; ctx.strokeText(txt, x0, y0);
      ctx.fillStyle = 'rgba(190,208,238,0.62)'; ctx.fillText(txt, x0, y0);
    }
    ctx.letterSpacing = '0px';
    // station names by importance
    const access = S.mode === 'access' && this.tree;
    const Kl = access ? Math.floor(14 * Math.pow(zr, 1.7)) : Math.floor(5 * Math.pow(zr, 1.9));
    if (zr < 2.4 && !access) return;
    ctx.font = '500 10.5px "Inter", system-ui, -apple-system, "Segoe UI", sans-serif';
    const order = this._order || (this._order = Array.from({ length: M.st.n }, (_, i) => i).sort((a, b) => this.rank[a] - this.rank[b]));
    let shown = 0;
    for (let i = 0; i < order.length && i < Kl && shown < 260; i++) {
      const s = order[i];
      const x = cam.sx(M.st.x[s]), y = cam.sy(M.st.y[s]);
      if (x < 0 || y < 0 || x > W || y > H) continue;
      let txt = M.st.name[s];
      let tcol = null;
      if (access) {
        const t = this.tree.router.earliest[s] - this.tree.router.T;
        if (s === this.tree.router.origin) tcol = '#ffffff';
        else if (t < Infinity) { txt += '  ' + durShort(t); tcol = BANDS[bandOf(t)].color; }
      }
      const w = ctx.measureText(txt).width;
      const x0 = x + 7, y0 = y;
      if (!fits(x0 - 2, y0 - 7, x0 + w + 2, y0 + 7)) continue;
      occ.push([x0 - 2, y0 - 7, x0 + w + 2, y0 + 7]);
      ctx.lineWidth = 3.2; ctx.strokeStyle = 'rgba(5,9,16,0.9)'; ctx.strokeText(txt, x0, y0);
      ctx.fillStyle = 'rgba(224,234,252,0.88)';
      ctx.fillText(txt, x0, y0);
      if (tcol) {
        const nm = M.st.name[s];
        const wn = ctx.measureText(nm).width;
        ctx.fillStyle = tcol; ctx.fillText(txt.slice(nm.length), x0 + wn, y0);
      }
      shown++;
    }
  }

  // ------------------------------------------------------------------ dynamic layer
  drawDyn(S, now) {
    const ctx = this.d, cam = this.cam, M = this.M, D = this.D;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;
    ctx.clearRect(0, 0, this.dc.width, this.dc.height);
    ctx.lineJoin = 'round'; ctx.lineCap = 'round';
    const zr = cam.scale / cam.fitScale;
    const zf = clamp(Math.pow(zr, 0.32), 1, 2.4);
    const pulse = 0.5 + 0.5 * Math.sin(now / 340);

    // highlighted corridor (flow list hover)
    if (S.hoverCode >= 0) {
      this._world(ctx);
      ctx.globalCompositeOperation = 'lighter';
      const p = this.pathOfCode(S.hoverCode);
      this._stroke(ctx, p, 9 * zf, 'rgba(255,255,255,1)', 0.12);
      this._stroke(ctx, p, 2.6 * zf, 'rgba(255,255,255,1)', 0.9);
      ctx.globalCompositeOperation = 'source-over';
    }
    if (S.hoverEdge >= 0) {
      this._world(ctx);
      const p = this._pathOf([S.hoverEdge]);
      this._stroke(ctx, p, 4 * zf, 'rgba(255,255,255,1)', 0.85);
    }

    // accessibility journey (hover)
    if (S.mode === 'access' && S.journey && S.journey.length) {
      this._world(ctx);
      ctx.globalCompositeOperation = 'lighter';
      for (const leg of S.journey) {
        if (leg.type === 'ride') {
          const tr = D.trips[leg.trip];
          for (let i = leg.i0; i < leg.i1; i++) {
            const p = this.legPath(tr.legs[i]);
            this._stroke(ctx, p, 8 * zf, 'rgba(255,255,255,1)', 0.18);
            this._stroke(ctx, p, 2.6 * zf, 'rgba(255,255,255,1)', 0.95);
          }
        } else {
          const p = new Path2D(); p.moveTo(M.st.x[leg.from], M.st.y[leg.from]); p.lineTo(M.st.x[leg.to], M.st.y[leg.to]);
          ctx.setLineDash([4 / cam.scale, 4 / cam.scale]);
          this._stroke(ctx, p, 2 * zf, 'rgba(255,255,255,1)', 0.9);
          ctx.setLineDash([]);
        }
      }
      ctx.globalCompositeOperation = 'source-over';
      this._screen(ctx);
      for (const leg of S.journey) {
        for (const s of [leg.from, leg.to]) {
          const x = cam.sx(M.st.x[s]), y = cam.sy(M.st.y[s]);
          ctx.beginPath(); ctx.arc(x, y, 4.2, 0, 6.2832);
          ctx.fillStyle = '#fff'; ctx.fill(); ctx.lineWidth = 1.5; ctx.strokeStyle = 'rgba(4,8,14,0.9)'; ctx.stroke();
        }
      }
    }

    // selected train route
    const sel = S.selTrip >= 0 ? D.trips[S.selTrip] : null;
    let selPos = null;
    if (sel) {
      this._world(ctx);
      const rgb = CATS[sel.cat].rgb;
      const st = trainState(M, sel, S.t, this._st);
      const cur = st ? this._st.seg : (S.t < sel.start ? -1 : sel.legs.length);
      ctx.globalCompositeOperation = 'lighter';
      for (let i = 0; i < sel.legs.length; i++) {
        const p = this.legPath(sel.legs[i]);
        if (i < cur) this._stroke(ctx, p, 2.2 * zf, 'rgba(210,225,255,1)', 0.28);
        else {
          this._stroke(ctx, p, 8 * zf, rgba(rgb, 1), 0.14);
          this._stroke(ctx, p, 2.6 * zf, rgba(rgb, 1), 0.95);
        }
      }
      ctx.globalCompositeOperation = 'source-over';
      this._screen(ctx);
      // stops
      ctx.font = '500 10.5px "Inter", system-ui, sans-serif'; ctx.textBaseline = 'middle';
      for (let i = 0; i < sel.st.length; i++) {
        const s = sel.st[i];
        if (sel.fl[i] === 3) continue;
        const x = cam.sx(M.st.x[s]), y = cam.sy(M.st.y[s]);
        const end = i === 0 || i === sel.st.length - 1;
        ctx.beginPath(); ctx.arc(x, y, end ? 5 : 3.2, 0, 6.2832);
        ctx.fillStyle = i <= cur ? 'rgba(20,30,48,1)' : 'rgba(10,16,26,1)'; ctx.fill();
        ctx.lineWidth = end ? 2.2 : 1.6; ctx.strokeStyle = i <= cur ? 'rgba(190,205,235,0.8)' : rgba(rgb, 1); ctx.stroke();
        if (end || zr > 3) {
          const txt = M.st.name[s];
          ctx.lineWidth = 3.2; ctx.strokeStyle = 'rgba(5,9,16,0.92)'; ctx.strokeText(txt, x + 8, y - 8);
          ctx.fillStyle = 'rgba(235,242,255,0.95)'; ctx.fillText(txt, x + 8, y - 8);
        }
      }
      if (st) selPos = { x: this._st.x, y: this._st.y };
    }

    // trains
    const dr = this.drawn;
    dr.n = 0;
    const showTrains = S.mode === 'live' || S.showTrains;
    if (showTrains) {
      this._screen(ctx);
      ctx.globalCompositeOperation = 'lighter';
      const hov = S.hoverCat;
      const bySz = clamp(Math.pow(zr, 0.22), 1, 2.1);
      const trails = [[], [], []];
      const st = this._st, pt = this._pt;
      const trips = D.trips, t = S.t;
      const W = cam.W, H = cam.H;
      for (let i = 0; i < trips.length; i++) {
        const tr = trips[i];
        if (!S.enabled[tr.cat] || tr.start > t || tr.end < t) continue;
        if (!trainState(M, tr, t, st)) continue;
        const x = cam.sx(st.x), y = cam.sy(st.y);
        if (x < -40 || y < -40 || x > W + 40 || y > H + 40) continue;
        if (dr.n < dr.x.length) { dr.x[dr.n] = x; dr.y[dr.n] = y; dr.t[dr.n] = i; dr.n++; }
        const c = tr.cat;
        const dim = hov >= 0 && hov !== c ? 0.2 : 1;
        const R = TRAIN_SIZE[c] * bySz;
        if (st.moving) {
          // comet trail along the track
          const L = TRAIL_PX[c] * Math.sqrt(bySz) / cam.scale;
          pointOnLeg(st.leg, st.dist - L * 0.45, pt); const x1 = cam.sx(pt.x), y1 = cam.sy(pt.y);
          pointOnLeg(st.leg, st.dist - L, pt); const x2 = cam.sx(pt.x), y2 = cam.sy(pt.y);
          trails[c].push(x, y, x1, y1, x2, y2, dim);
        }
        const g = R * 4.4;
        ctx.globalAlpha = (st.moving ? 0.9 : 0.5) * dim;
        ctx.drawImage(this.sprites[c], x - g, y - g, 2 * g, 2 * g);
        ctx.globalAlpha = (st.moving ? 1 : 0.65) * dim;
        ctx.beginPath(); ctx.arc(x, y, st.moving ? R * 0.62 : R * 0.45, 0, 6.2832);
        ctx.fillStyle = st.moving ? '#fff' : CATS[c].color; ctx.fill();
      }
      // trails (batched per category and dim level)
      for (let c = 0; c < 3; c++) {
        const arr = trails[c];
        if (!arr.length) continue;
        const rgb = CATS[c].rgb;
        for (const pass of [0, 1]) {
          ctx.beginPath();
          let dimv = 1;
          for (let k = 0; k < arr.length; k += 7) {
            dimv = arr[k + 6];
            if (pass === 0) { ctx.moveTo(arr[k], arr[k + 1]); ctx.lineTo(arr[k + 2], arr[k + 3]); }
            else { ctx.moveTo(arr[k + 2], arr[k + 3]); ctx.lineTo(arr[k + 4], arr[k + 5]); }
          }
          ctx.lineWidth = (pass === 0 ? 2.2 : 1.5) * Math.sqrt(bySz) * (c === 0 ? 1.15 : c === 2 ? 0.85 : 1);
          ctx.strokeStyle = rgba(rgb, 1);
          ctx.globalAlpha = (pass === 0 ? 0.55 : 0.22) * (hov >= 0 && dimv < 1 ? 0.3 : 1);
          ctx.stroke();
        }
      }
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = 'source-over';
    }

    // hover / selection rings
    this._screen(ctx);
    if (selPos) {
      const x = cam.sx(selPos.x), y = cam.sy(selPos.y);
      const rgb = CATS[sel.cat].rgb;
      ctx.beginPath(); ctx.arc(x, y, 11 + 3 * pulse, 0, 6.2832);
      ctx.lineWidth = 1.6; ctx.strokeStyle = rgba(rgb, 0.95); ctx.stroke();
      ctx.beginPath(); ctx.arc(x, y, 17 + 6 * pulse, 0, 6.2832);
      ctx.lineWidth = 1; ctx.strokeStyle = rgba(rgb, 0.35 * (1 - pulse * 0.5)); ctx.stroke();
      S.selPos = selPos;
    } else S.selPos = null;
    if (S.hoverTrip >= 0 && S.hoverTrip !== S.selTrip) {
      const tr = D.trips[S.hoverTrip];
      if (trainState(M, tr, S.t, this._st)) {
        const x = cam.sx(this._st.x), y = cam.sy(this._st.y);
        ctx.beginPath(); ctx.arc(x, y, 10, 0, 6.2832); ctx.lineWidth = 1.4; ctx.strokeStyle = 'rgba(255,255,255,0.85)'; ctx.stroke();
      }
    }
    const ringStation = (s, col, r0, anim) => {
      const x = cam.sx(M.st.x[s]), y = cam.sy(M.st.y[s]);
      ctx.beginPath(); ctx.arc(x, y, r0 + (anim ? 4 * pulse : 0), 0, 6.2832);
      ctx.lineWidth = 1.8; ctx.strokeStyle = col; ctx.stroke();
      if (anim) {
        ctx.beginPath(); ctx.arc(x, y, r0 + 8 + 10 * pulse, 0, 6.2832);
        ctx.lineWidth = 1; ctx.strokeStyle = col.replace(/[\d.]+\)$/, (0.5 * (1 - pulse)) + ')'); ctx.stroke();
      }
    };
    if (S.selStation >= 0) ringStation(S.selStation, 'rgba(255,255,255,0.95)', 9, true);
    if (S.hoverStation >= 0) ringStation(S.hoverStation, 'rgba(255,255,255,0.8)', 8, false);
    if (S.mode === 'access' && this.tree) {
      ringStation(this.tree.router.origin, 'rgba(255,255,255,0.95)', 10, true);
    }
  }

  // ------------------------------------------------------------------ picking
  pickTrain(sx, sy, r = 11) {
    const dr = this.drawn;
    let best = -1, bd = r * r;
    for (let i = 0; i < dr.n; i++) {
      const d = (dr.x[i] - sx) ** 2 + (dr.y[i] - sy) ** 2;
      if (d < bd) { bd = d; best = dr.t[i]; }
    }
    return best;
  }
  pickStation(sx, sy, S, r = 11) {
    const M = this.M, cam = this.cam;
    const zr = cam.scale / cam.fitScale;
    const K = S.mode === 'access' ? M.st.n : Math.floor(18 * Math.pow(zr, 1.9));
    let best = -1, bd = r * r;
    for (let s = 0; s < M.st.n; s++) {
      if (this.rank[s] >= K) continue;
      const d = (cam.sx(M.st.x[s]) - sx) ** 2 + (cam.sy(M.st.y[s]) - sy) ** 2;
      if (d < bd) { bd = d; best = s; }
    }
    return best;
  }
  pickEdge(sx, sy, r = 7) {
    const M = this.M, cam = this.cam, E = M.edges;
    const wx = cam.wx(sx), wy = cam.wy(sy), tol = r / cam.scale;
    let best = -1, bd = tol * tol;
    for (let e = 0; e < E.n; e++) {
      const b = E.bbox;
      if (wx < b[4 * e] - tol || wx > b[4 * e + 2] + tol || wy < b[4 * e + 1] - tol || wy > b[4 * e + 3] + tol) continue;
      const xy = E.xy[e];
      for (let k = 0; k < xy.length - 2; k += 2) {
        const ax = xy[k], ay = xy[k + 1], bx = xy[k + 2], by = xy[k + 3];
        const dx = bx - ax, dy = by - ay;
        const l2 = dx * dx + dy * dy;
        let u = l2 ? ((wx - ax) * dx + (wy - ay) * dy) / l2 : 0;
        u = u < 0 ? 0 : u > 1 ? 1 : u;
        const px = ax + u * dx - wx, py = ay + u * dy - wy;
        const d = px * px + py * py;
        if (d < bd) { bd = d; best = e; }
      }
    }
    return best;
  }
}

function hex(h) { const n = parseInt(h.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }

tool_input.content:
:root {
  --bg: #050910;
  --panel: rgba(9, 15, 26, 0.76);
  --panel-solid: #0a111c;
  --line: rgba(130, 170, 235, 0.16);
  --line-strong: rgba(150, 190, 255, 0.3);
  --text: #dbe6f7;
  --text-2: #9db0cc;
  --muted: #6b7f9e;
  --accent: #3fd0ff;
  --tgv: #ff4d94;
  --ic: #ffb020;
  --ter: #3fd0ff;
  --font: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
  --left: 336px;
  --right: 372px;
  --top: 58px;
  --bottom: 76px;
}
* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; background: var(--bg); color: var(--text); font: 13px/1.4 var(--font); overflow: hidden; -webkit-font-smoothing: antialiased; }
button { font: inherit; color: inherit; cursor: pointer; }
h1, h2, h3, p, ol, ul { margin: 0; padding: 0; }
ol, ul { list-style: none; }
.num { font-variant-numeric: tabular-nums; font-family: var(--mono); letter-spacing: -0.02em; }

#app { position: fixed; inset: 0; }
#stage { position: absolute; inset: 0; background:
  radial-gradient(1200px 800px at 55% 45%, #0e1a2e 0%, #08111f 45%, #04070d 100%); cursor: grab; touch-action: none; }
#stage.drag { cursor: grabbing; }
#stage.pointer { cursor: pointer; }
#stage canvas { position: absolute; left: 0; top: 0; }
#night { position: absolute; inset: 0; pointer-events: none; background: #04123a; opacity: 0; mix-blend-mode: multiply; }
#vignette { position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse at 52% 48%, transparent 52%, rgba(2, 4, 9, 0.62) 100%),
    repeating-linear-gradient(0deg, rgba(120, 170, 255, 0.018) 0 1px, transparent 1px 3px); }

/* ------------------------------------------------------------------ header */
#top { position: absolute; left: 0; right: 0; top: 0; height: var(--top); display: flex; align-items: center; justify-content: space-between; padding: 0 16px; gap: 16px;
  background: linear-gradient(180deg, rgba(5, 9, 16, 0.92), rgba(5, 9, 16, 0.55) 70%, transparent); z-index: 20; pointer-events: none; }
#top > * { pointer-events: auto; }
#top::after { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 2px; background: linear-gradient(90deg, var(--tgv), var(--ic) 50%, var(--ter)); opacity: 0.8; pointer-events: none; }
.brand { display: flex; align-items: center; gap: 12px; min-width: 250px; }
.logo { position: relative; width: 30px; height: 30px; }
.logo i { position: absolute; inset: 0; border-radius: 50%; border: 1.5px solid; opacity: 0.9; }
.logo i:nth-child(1) { border-color: var(--tgv); inset: 0; animation: spin 14s linear infinite; border-right-color: transparent; }
.logo i:nth-child(2) { border-color: var(--ic); inset: 5px; animation: spin 9s linear infinite reverse; border-bottom-color: transparent; }
.logo i:nth-child(3) { border-color: var(--ter); inset: 10px; background: var(--ter); box-shadow: 0 0 12px var(--ter); }
@keyframes spin { to { transform: rotate(360deg); } }
.brand h1 { font-size: 15px; font-weight: 700; letter-spacing: 0.22em; text-transform: uppercase; }
.brand p { font-size: 10.5px; letter-spacing: 0.14em; color: var(--muted); text-transform: uppercase; margin-top: 1px; }

#modes { display: flex; gap: 4px; padding: 3px; border: 1px solid var(--line); border-radius: 10px; background: rgba(8, 13, 22, 0.7); backdrop-filter: blur(10px); }
#modes button { border: 0; background: transparent; color: var(--text-2); padding: 7px 14px; border-radius: 7px; font-weight: 600; letter-spacing: 0.04em; display: flex; gap: 8px; align-items: center; transition: background 0.2s, color 0.2s; }
#modes button b { font: 600 10px var(--mono); color: var(--muted); }
#modes button:hover { color: #fff; background: rgba(120, 160, 230, 0.1); }
#modes button.on { color: #04101c; background: linear-gradient(180deg, #7fe0ff, #3fd0ff); box-shadow: 0 0 18px rgba(63, 208, 255, 0.4); }
#modes button.on b { color: rgba(4, 16, 28, 0.6); }
.top-right { display: flex; gap: 10px; align-items: center; min-width: 250px; justify-content: flex-end; }
#days { display: flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; background: rgba(8, 13, 22, 0.7); backdrop-filter: blur(10px); }
#days button { border: 0; background: transparent; padding: 7px 11px; color: var(--text-2); font-size: 12px; }
#days button + button { border-left: 1px solid var(--line); }
#days button.on { background: rgba(63, 208, 255, 0.16); color: #fff; }
.search { position: relative; }
.search svg { position: absolute; left: 10px; top: 9px; width: 15px; height: 15px; stroke: var(--muted); fill: none; stroke-width: 1.6; pointer-events: none; }
.search input { width: 230px; padding: 8px 10px 8px 32px; border-radius: 8px; border: 1px solid var(--line); background: rgba(8, 13, 22, 0.75); backdrop-filter: blur(10px); color: var(--text); font: inherit; outline: none; }
.search input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(63, 208, 255, 0.15); }
#results { position: absolute; right: 0; top: 38px; width: 320px; max-height: 380px; overflow: auto; background: var(--panel-solid); border: 1px solid var(--line-strong); border-radius: 10px; box-shadow: 0 18px 50px rgba(0, 0, 0, 0.6); display: none; }
#results.open { display: block; }
#results button { display: flex; width: 100%; gap: 10px; align-items: center; text-align: left; padding: 8px 12px; border: 0; background: transparent; border-bottom: 1px solid rgba(130, 170, 235, 0.08); }
#results button:hover, #results button.act { background: rgba(63, 208, 255, 0.1); }
#results small { color: var(--muted); margin-left: auto; }

/* ------------------------------------------------------------------ panels */
aside { position: absolute; z-index: 10; top: calc(var(--top) + 4px); bottom: calc(var(--bottom) + 14px); overflow-y: auto; overflow-x: hidden; scrollbar-width: thin; scrollbar-color: rgba(130, 170, 235, 0.3) transparent; display: flex; flex-direction: column; gap: 10px; }
#left { left: 14px; width: var(--left); }
#right { right: 14px; width: var(--right); }
#right[hidden] { display: none; }
.card { background: var(--panel); backdrop-filter: blur(14px) saturate(1.3); border: 1px solid var(--line); border-radius: 12px; padding: 13px 14px; box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(180, 210, 255, 0.05); flex: none; }
.card h2 { font-size: 10.5px; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; color: var(--text-2); display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; gap: 8px; }
.card h2 .hint { font-weight: 500; letter-spacing: 0.04em; text-transform: none; color: var(--muted); font-size: 11px; }
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: 6px; overflow: hidden; letter-spacing: 0; text-transform: none; }
.seg button { border: 0; background: transparent; padding: 3px 8px; font-size: 11px; color: var(--muted); }
.seg button + button { border-left: 1px solid var(--line); }
.seg button.on { background: rgba(63, 208, 255, 0.18); color: #fff; }

/* big live counter */
.big { display: flex; align-items: baseline; gap: 10px; }
.big .n { font: 600 40px/1 var(--mono); letter-spacing: -0.04em; color: #fff; text-shadow: 0 0 24px rgba(63, 208, 255, 0.45); }
.big .l { color: var(--text-2); font-size: 12px; }
.stack { display: flex; height: 6px; border-radius: 3px; overflow: hidden; gap: 2px; margin: 10px 0 8px; background: rgba(130, 170, 235, 0.08); }
.stack i { display: block; height: 100%; transition: flex-basis 0.4s; min-width: 0; }
.cats { display: flex; flex-direction: column; gap: 3px; }
.cat { display: grid; grid-template-columns: 14px 1fr auto; align-items: center; gap: 9px; padding: 7px 8px; border-radius: 8px; border: 1px solid transparent; background: transparent; width: 100%; text-align: left; transition: background 0.15s, opacity 0.2s, border-color 0.15s; }
.cat:hover { background: rgba(130, 170, 235, 0.08); border-color: var(--line); }
.cat .sw { width: 11px; height: 11px; border-radius: 50%; background: var(--c); box-shadow: 0 0 10px var(--c); }
.cat .nm { font-weight: 600; }
.cat .nm small { display: block; font-weight: 400; color: var(--muted); font-size: 11px; }
.cat .v { text-align: right; font: 600 17px var(--mono); letter-spacing: -0.03em; }
.cat .v small { display: block; font: 400 10.5px var(--font); color: var(--muted); letter-spacing: 0; }
.cat.off { opacity: 0.38; }
.cat.off .sw { background: transparent; box-shadow: none; border: 1.5px solid var(--c); }
.tools { display: flex; gap: 6px; margin-top: 8px; flex-wrap: wrap; }
.chip { border: 1px solid var(--line); background: rgba(130, 170, 235, 0.06); border-radius: 999px; padding: 4px 10px; font-size: 11.5px; color: var(--text-2); }
.chip:hover { border-color: var(--line-strong); color: #fff; }
.chip.on { background: rgba(63, 208, 255, 0.18); border-color: rgba(63, 208, 255, 0.5); color: #fff; }

/* travel-time classes */
.bands { display: flex; flex-direction: column; gap: 5px; }
.band { display: grid; grid-template-columns: 12px 58px 1fr 46px; gap: 8px; align-items: center; font-size: 12px; }
.band .sw { width: 12px; height: 12px; border-radius: 3px; background: var(--c); box-shadow: 0 0 9px var(--c); }
.band .bar { height: 8px; border-radius: 4px; background: rgba(130, 170, 235, 0.08); overflow: hidden; }
.band .bar i { display: block; height: 100%; background: var(--c); border-radius: 4px; box-shadow: 0 0 10px var(--c); transition: width 0.35s; }
.band .c { text-align: right; font: 600 12px var(--mono); }
.origin { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; padding: 9px 10px; border-radius: 9px; background: rgba(255, 255, 255, 0.05); border: 1px solid var(--line); }
.origin .dot { width: 12px; height: 12px; border-radius: 50%; background: #fff; box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.2), 0 0 16px #fff; flex: none; }
.origin b { display: block; font-size: 14px; }
.origin small { color: var(--text-2); }
.note { color: var(--muted); font-size: 11.5px; margin-top: 9px; line-height: 1.45; }
.note b { color: var(--text-2); font-weight: 600; }

/* flow legend */
.grad { height: 10px; border-radius: 5px; margin: 6px 0 4px; box-shadow: 0 0 14px rgba(255, 120, 60, 0.25); }
.grad-l { display: flex; justify-content: space-between; font: 11px var(--mono); color: var(--text-2); }
.corr { margin-top: 10px; display: flex; flex-direction: column; gap: 1px; }
.corr button { display: grid; grid-template-columns: 1fr auto; gap: 10px; border: 0; background: transparent; text-align: left; padding: 5px 6px; border-radius: 6px; align-items: center; }
.corr button:hover { background: rgba(130, 170, 235, 0.1); }
.corr .nm { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 12px; }
.corr .nm small { color: var(--muted); margin-left: 6px; }
.corr .vv { font: 600 12px var(--mono); }
.corr .meter { grid-column: 1 / -1; height: 3px; border-radius: 2px; background: rgba(130, 170, 235, 0.08); overflow: hidden; }
.corr .meter i { display: block; height: 100%; border-radius: 2px; }

/* profile chart */
#profile { position: relative; }
#profile svg { display: block; width: 100%; height: 118px; overflow: visible; }
#profile .grid line { stroke: rgba(130, 170, 235, 0.1); stroke-width: 1; }
#profile .ax text { fill: var(--muted); font: 10px var(--mono); }
#profile .area { stroke: #0a111c; stroke-width: 1.5; }
#profile .head { stroke: #fff; stroke-width: 1.3; }
#profile .cross { stroke: rgba(255, 255, 255, 0.55); stroke-width: 1; stroke-dasharray: 3 3; }
#ptip { position: absolute; pointer-events: none; z-index: 5; background: var(--panel-solid); border: 1px solid var(--line-strong); border-radius: 8px; padding: 7px 9px; font-size: 11.5px; display: none; white-space: nowrap; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5); }
#ptip .r { display: flex; gap: 8px; align-items: center; justify-content: space-between; }
#ptip .r i { width: 8px; height: 8px; border-radius: 2px; display: inline-block; }
#ptip b { font-family: var(--mono); margin-left: 12px; }

/* busiest stations */
#busy { display: flex; flex-direction: column; gap: 2px; }
#busy button { display: grid; grid-template-columns: 18px 1fr auto; gap: 8px; width: 100%; border: 0; background: transparent; text-align: left; padding: 4px 4px; border-radius: 6px; align-items: center; }
#busy button:hover { background: rgba(130, 170, 235, 0.1); }
#busy .rk { font: 11px var(--mono); color: var(--muted); }
#busy .nm { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#busy .v { font: 600 12px var(--mono); }
#busy .m { grid-column: 2 / 4; display: flex; height: 3px; gap: 1px; border-radius: 2px; overflow: hidden; background: rgba(130, 170, 235, 0.07); }
#busy .m i { display: block; height: 100%; }

/* ------------------------------------------------------------------ details panel */
#right .card { padding: 0; overflow: hidden; }
.dh { padding: 14px 14px 12px; border-bottom: 1px solid var(--line); position: relative; background: linear-gradient(180deg, color-mix(in srgb, var(--c, #3fd0ff) 14%, transparent), transparent); }
.dh .x { position: absolute; right: 8px; top: 8px; width: 26px; height: 26px; border-radius: 6px; border: 1px solid var(--line); background: rgba(130, 170, 235, 0.06); color: var(--text-2); font-size: 15px; line-height: 1; }
.dh .x:hover { color: #fff; border-color: var(--line-strong); }
.badge { display: inline-flex; align-items: center; gap: 7px; padding: 3px 9px 3px 7px; border-radius: 999px; font-weight: 700; font-size: 11.5px; letter-spacing: 0.04em; background: color-mix(in srgb, var(--c) 18%, transparent); border: 1px solid color-mix(in srgb, var(--c) 55%, transparent); color: #fff; }
.badge i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); box-shadow: 0 0 8px var(--c); }
.dh h3 { font-size: 16px; line-height: 1.25; margin: 9px 26px 3px 0; font-weight: 700; }
.dh .sub { color: var(--text-2); font-size: 12px; }
.kv { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line); border-bottom: 1px solid var(--line); }
.kv div { background: rgba(8, 13, 22, 0.9); padding: 8px 12px; }
.kv small { display: block; color: var(--muted); font-size: 10.5px; letter-spacing: 0.08em; text-transform: uppercase; }
.kv b { font: 600 14px var(--mono); letter-spacing: -0.02em; }
.progress { padding: 11px 14px; border-bottom: 1px solid var(--line); }
.progress .pt { display: flex; justify-content: space-between; font-size: 12px; margin-bottom: 7px; gap: 8px; }
.progress .pb { height: 5px; border-radius: 3px; background: rgba(130, 170, 235, 0.12); overflow: hidden; }
.progress .pb i { display: block; height: 100%; background: var(--c); box-shadow: 0 0 10px var(--c); width: 0; }
.actions { display: flex; gap: 6px; padding: 10px 14px; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.tt { max-height: calc(100vh - var(--top) - var(--bottom) - 330px); min-height: 160px; overflow-y: auto; scrollbar-width: thin; scrollbar-color: rgba(130, 170, 235, 0.3) transparent; padding: 6px 0 10px; position: relative; }
.stop { display: grid; grid-template-columns: 62px 18px 1fr; align-items: stretch; padding: 0 14px 0 8px; position: relative; cursor: default; }
.stop .tm { text-align: right; padding: 7px 4px 7px 0; font: 12px var(--mono); color: var(--text-2); line-height: 1.25; }
.stop .tm b { color: #fff; font-weight: 600; display: block; }
.stop .tm s { text-decoration: none; color: var(--muted); display: block; }
.stop .rail { position: relative; }
.stop .rail::before { content: ""; position: absolute; left: 8px; top: 0; bottom: 0; width: 2px; background: color-mix(in srgb, var(--c) 55%, transparent); }
.stop:first-child .rail::before { top: 14px; }
.stop:last-child .rail::before { bottom: calc(100% - 14px); }
.stop.done .rail::before { background: rgba(160, 180, 215, 0.3); }
.stop .rail::after { content: ""; position: absolute; left: 4px; top: 10px; width: 10px; height: 10px; border-radius: 50%; background: var(--panel-solid); border: 2px solid var(--c); }
.stop.done .rail::after { border-color: rgba(160, 180, 215, 0.55); }
.stop.pass .rail::after { width: 6px; height: 6px; left: 6px; top: 12px; border-width: 1.5px; opacity: 0.6; }
.stop.cur .rail::after { background: var(--c); box-shadow: 0 0 0 4px color-mix(in srgb, var(--c) 30%, transparent), 0 0 14px var(--c); }
.stop.end .rail::after { background: var(--c); }
.stop .nm { padding: 6px 0 6px 6px; border-radius: 6px; min-width: 0; }
.stop .nm button.st { border: 0; background: none; padding: 0; text-align: left; font-weight: 600; font-size: 13px; color: var(--text); display: block; }
.stop .nm button.st:hover { color: #fff; text-decoration: underline; text-decoration-color: var(--accent); }
.stop.pass .nm button.st { font-weight: 400; color: var(--muted); }
.stop.done .nm button.st { color: var(--text-2); }
.stop .nm .meta { color: var(--muted); font-size: 11px; }
.conn-btn { margin-top: 3px; border: 1px solid var(--line); background: rgba(130, 170, 235, 0.06); border-radius: 999px; padding: 1px 8px; font-size: 11px; color: var(--text-2); }
.conn-btn:hover { border-color: var(--line-strong); color: #fff; }
.conn-btn.open { border-color: var(--accent); color: #fff; }
.conns { margin: 5px 0 4px; display: flex; flex-direction: column; gap: 2px; }
.conns button { display: grid; grid-template-columns: 44px 10px 1fr auto; gap: 7px; align-items: center; border: 0; background: rgba(130, 170, 235, 0.06); padding: 4px 7px; border-radius: 6px; text-align: left; font-size: 11.5px; }
.conns button:hover { background: rgba(130, 170, 235, 0.14); }
.conns .t { font: 12px var(--mono); color: #fff; }
.conns .d { width: 8px; height: 8px; border-radius: 50%; background: var(--c); box-shadow: 0 0 6px var(--c); }
.conns .w { color: var(--muted); font: 11px var(--mono); }
.conns span.l { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* station panel */
.hist { display: flex; align-items: flex-end; gap: 2px; height: 46px; padding: 10px 14px 0; }
.hist i { flex: 1; min-width: 0; border-radius: 2px 2px 0 0; background: rgba(160, 190, 240, 0.35); position: relative; }
.hist i.now { background: #fff; box-shadow: 0 0 8px #fff; }
.hist-l { display: flex; justify-content: space-between; padding: 3px 14px 8px; font: 10px var(--mono); color: var(--muted); border-bottom: 1px solid var(--line); }
.tabs { display: flex; padding: 8px 14px 0; gap: 4px; }
.tabs button { border: 0; background: transparent; padding: 6px 10px; border-radius: 6px 6px 0 0; color: var(--muted); font-weight: 600; border-bottom: 2px solid transparent; }
.tabs button.on { color: #fff; border-bottom-color: var(--accent); }
.board { max-height: calc(100vh - var(--top) - var(--bottom) - 440px); min-height: 150px; overflow-y: auto; padding: 4px 8px 10px; scrollbar-width: thin; scrollbar-color: rgba(130, 170, 235, 0.3) transparent; }
.board button { display: grid; grid-template-columns: 44px 10px 1fr; gap: 8px; width: 100%; align-items: center; border: 0; background: transparent; padding: 6px 6px; border-radius: 7px; text-align: left; }
.board button:hover { background: rgba(130, 170, 235, 0.1); }
.board .t { font: 600 13px var(--mono); }
.board .d { width: 9px; height: 9px; border-radius: 50%; background: var(--c); box-shadow: 0 0 7px var(--c); }
.board .to { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.board .to small { display: block; color: var(--muted); font-size: 11px; }
.board .past { opacity: 0.4; }
.board .sep { text-align: center; color: var(--accent); font-size: 10.5px; letter-spacing: 0.14em; text-transform: uppercase; padding: 6px 0; border-top: 1px dashed rgba(63, 208, 255, 0.4); margin-top: 4px; }

/* journey in tooltip / panel */
.jr { display: flex; flex-direction: column; gap: 4px; margin-top: 6px; }
.jr div { display: grid; grid-template-columns: 44px 1fr; gap: 8px; font-size: 11.5px; }
.jr .t { font: 11.5px var(--mono); color: var(--text-2); }
.jr .w { color: var(--muted); }

/* ------------------------------------------------------------------ tooltip */
#tooltip { position: absolute; z-index: 30; pointer-events: none; display: none; max-width: 320px; background: rgba(8, 13, 22, 0.94); border: 1px solid var(--line-strong); border-radius: 10px; padding: 9px 11px; box-shadow: 0 14px 40px rgba(0, 0, 0, 0.6); backdrop-filter: blur(10px); }
#tooltip .h { display: flex; align-items: center; gap: 8px; font-weight: 700; }
#tooltip .h i { width: 9px; height: 9px; border-radius: 50%; background: var(--c); box-shadow: 0 0 8px var(--c); flex: none; }
#tooltip .s { color: var(--text-2); font-size: 12px; margin-top: 2px; }
#tooltip .big2 { font: 600 20px var(--mono); letter-spacing: -0.03em; margin-top: 3px; }

/* ------------------------------------------------------------------ zoom + hint */
#zoom { position: absolute; right: 14px; bottom: calc(var(--bottom) + 18px); z-index: 12; display: flex; flex-direction: column; gap: 4px; transition: right 0.25s; }
#app.has-right #zoom { right: calc(var(--right) + 28px); }
#zoom button { width: 34px; height: 34px; border-radius: 8px; border: 1px solid var(--line); background: var(--panel); backdrop-filter: blur(10px); font-size: 18px; color: var(--text-2); display: grid; place-items: center; }
#zoom button:hover { color: #fff; border-color: var(--line-strong); }
#zoom svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 1.6; }
#hint { position: absolute; z-index: 11; left: 50%; top: calc(var(--top) + 8px); transform: translateX(-50%); padding: 8px 16px; border-radius: 999px; background: rgba(8, 13, 22, 0.8); border: 1px solid var(--line-strong); backdrop-filter: blur(10px); color: var(--text); font-size: 12.5px; opacity: 0; transition: opacity 0.35s; pointer-events: none; white-space: nowrap; margin-left: calc((var(--left) - var(--right)) / 2); }
#hint.on { opacity: 1; }
#hint b { color: var(--accent); }

/* ------------------------------------------------------------------ timeline */
#timeline { position: absolute; left: 14px; right: 14px; bottom: 14px; height: var(--bottom); z-index: 15; display: grid; grid-template-columns: auto auto 1fr auto; align-items: center; gap: 16px; padding: 0 18px 0 14px; background: var(--panel); border: 1px solid var(--line); border-radius: 14px; backdrop-filter: blur(16px) saturate(1.3); box-shadow: 0 10px 40px rgba(0, 0, 0, 0.4); }
#play { width: 46px; height: 46px; border-radius: 50%; border: 1px solid rgba(63, 208, 255, 0.55); background: radial-gradient(circle at 50% 35%, rgba(63, 208, 255, 0.3), rgba(63, 208, 255, 0.06)); display: grid; place-items: center; box-shadow: 0 0 22px rgba(63, 208, 255, 0.25); }
#play:hover { box-shadow: 0 0 30px rgba(63, 208, 255, 0.5); }
#play svg { width: 18px; height: 18px; fill: #fff; }
.clock { font-family: var(--mono); display: flex; align-items: baseline; min-width: 128px; }
#clock { font-size: 36px; font-weight: 600; letter-spacing: -0.05em; color: #fff; text-shadow: 0 0 22px rgba(63, 208, 255, 0.5); }
#clockSec { font-size: 17px; color: var(--muted); margin-left: 2px; }
.scrub-wrap { min-width: 0; padding-top: 6px; }
#scrub { position: relative; height: 46px; cursor: ew-resize; border-radius: 6px; outline: none; touch-action: none; }
#scrub:focus-visible { box-shadow: 0 0 0 2px rgba(63, 208, 255, 0.5); }
#scrubCanvas { position: absolute; inset: 0; width: 100%; height: 100%; }
#scrubHead { position: absolute; top: -2px; bottom: 12px; width: 2px; background: #fff; box-shadow: 0 0 12px #fff, 0 0 3px #fff; border-radius: 1px; pointer-events: none; }
#scrubHead::before { content: ""; position: absolute; left: -5px; top: -1px; border: 6px solid transparent; border-top-color: #fff; border-bottom: 0; }
#scrubTip { position: absolute; bottom: calc(100% + 6px); transform: translateX(-50%); padding: 2px 7px; border-radius: 5px; background: var(--panel-solid); border: 1px solid var(--line-strong); font: 11px var(--mono); display: none; pointer-events: none; }
#speeds { display: flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
#speeds button { border: 0; background: transparent; padding: 7px 9px; color: var(--muted); font: 600 11.5px var(--mono); }
#speeds button + button { border-left: 1px solid var(--line); }
#speeds button:hover { color: #fff; }
#speeds button.on { background: rgba(63, 208, 255, 0.2); color: #fff; }

/* ------------------------------------------------------------------ loader */
#loader { position: absolute; inset: 0; z-index: 100; background: #04070d; display: grid; place-content: center; justify-items: center; gap: 18px; transition: opacity 0.7s, visibility 0.7s; }
#loader.done { opacity: 0; visibility: hidden; }
#loader .ring { width: 54px; height: 54px; border-radius: 50%; border: 2px solid rgba(63, 208, 255, 0.2); border-top-color: var(--accent); animation: spin 1s linear infinite; }
#loader p { color: var(--text-2); letter-spacing: 0.1em; text-transform: uppercase; font-size: 11.5px; }
#loader .bar { width: 240px; height: 3px; background: rgba(130, 170, 235, 0.15); border-radius: 2px; overflow: hidden; }
#loader .bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--tgv), var(--ic), var(--ter)); transition: width 0.2s; }

@media (max-width: 1180px) {
  :root { --left: 296px; --right: 340px; }
  .brand p, #modes button b { display: none; }
  .search input { width: 160px; }
}
@media (max-width: 900px) {
  #left { display: none; }
  #speeds, .brand-txt p { display: none; }
  #hint { margin-left: 0; }
}

:root {
  --bg: #050910;
  --panel: rgba(9, 15, 26, 0.76);
  --panel-solid: #0a111c;
  --line: rgba(130, 170, 235, 0.16);
  --line-strong: rgba(150, 190, 255, 0.3);
  --text: #dbe6f7;
  --text-2: #9db0cc;
  --muted: #6b7f9e;
  --accent: #3fd0ff;
  --tgv: #ff4d94;
  --ic: #ffb020;
  --ter: #3fd0ff;
  --font: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
  --left: 336px;
  --right: 372px;
  --top: 58px;
  --bottom: 76px;
}
* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; background: var(--bg); color: var(--text); font: 13px/1.4 var(--font); overflow: hidden; -webkit-font-smoothing: antialiased; }
button { font: inherit; color: inherit; cursor: pointer; }
h1, h2, h3, p, ol, ul { margin: 0; padding: 0; }
ol, ul { list-style: none; }
.num { font-variant-numeric: tabular-nums; font-family: var(--mono); letter-spacing: -0.02em; }

#app { position: fixed; inset: 0; }
#stage { position: absolute; inset: 0; background:
  radial-gradient(1200px 800px at 55% 45%, #0e1a2e 0%, #08111f 45%, #04070d 100%); cursor: grab; touch-action: none; }
#stage.drag { cursor: grabbing; }
#stage.pointer { cursor: pointer; }
#stage canvas { position: absolute; left: 0; top: 0; }
#night { position: absolute; inset: 0; pointer-events: none; background: #04123a; opacity: 0; mix-blend-mode: multiply; }
#vignette { position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse at 52% 48%, transparent 52%, rgba(2, 4, 9, 0.62) 100%),
    repeating-linear-gradient(0deg, rgba(120, 170, 255, 0.018) 0 1px, transparent 1px 3px); }

/* ------------------------------------------------------------------ header */
#top { position: absolute; left: 0; right: 0; top: 0; height: var(--top); display: flex; align-items: center; justify-content: space-between; padding: 0 16px; gap: 16px;
  background: linear-gradient(180deg, rgba(5, 9, 16, 0.92), rgba(5, 9, 16, 0.55) 70%, transparent); z-index: 20; pointer-events: none; }
#top > * { pointer-events: auto; }
#top::after { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 2px; background: linear-gradient(90deg, var(--tgv), var(--ic) 50%, var(--ter)); opacity: 0.8; pointer-events: none; }
.brand { display: flex; align-items: center; gap: 12px; min-width: 250px; }
.logo { position: relative; width: 30px; height: 30px; }
.logo i { position: absolute; inset: 0; border-radius: 50%; border: 1.5px solid; opacity: 0.9; }
.logo i:nth-child(1) { border-color: var(--tgv); inset: 0; animation: spin 14s linear infinite; border-right-color: transparent; }
.logo i:nth-child(2) { border-color: var(--ic); inset: 5px; animation: spin 9s linear infinite reverse; border-bottom-color: transparent; }
.logo i:nth-child(3) { border-color: var(--ter); inset: 10px; background: var(--ter); box-shadow: 0 0 12px var(--ter); }
@keyframes spin { to { transform: rotate(360deg); } }
.brand h1 { font-size: 15px; font-weight: 700; letter-spacing: 0.22em; text-transform: uppercase; }
.brand p { font-size: 10.5px; letter-spacing: 0.14em; color: var(--muted); text-transform: uppercase; margin-top: 1px; }

#modes { display: flex; gap: 4px; padding: 3px; border: 1px solid var(--line); border-radius: 10px; background: rgba(8, 13, 22, 0.7); backdrop-filter: blur(10px); }
#modes button { border: 0; background: transparent; color: var(--text-2); padding: 7px 14px; border-radius: 7px; font-weight: 600; letter-spacing: 0.04em; display: flex; gap: 8px; align-items: center; transition: background 0.2s, color 0.2s; }
#modes button b { font: 600 10px var(--mono); color: var(--muted); }
#modes button:hover { color: #fff; background: rgba(120, 160, 230, 0.1); }
#modes button.on { color: #04101c; background: linear-gradient(180deg, #7fe0ff, #3fd0ff); box-shadow: 0 0 18px rgba(63, 208, 255, 0.4); }
#modes button.on b { color: rgba(4, 16, 28, 0.6); }
.top-right { display: flex; gap: 10px; align-items: center; min-width: 250px; justify-content: flex-end; }
#days { display: flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; background: rgba(8, 13, 22, 0.7); backdrop-filter: blur(10px); }
#days button { border: 0; background: transparent; padding: 7px 11px; color: var(--text-2); font-size: 12px; }
#days button + button { border-left: 1px solid var(--line); }
#days button.on { background: rgba(63, 208, 255, 0.16); color: #fff; }
.search { position: relative; }
.search svg { position: absolute; left: 10px; top: 9px; width: 15px; height: 15px; stroke: var(--muted); fill: none; stroke-width: 1.6; pointer-events: none; }
.search input { width: 230px; padding: 8px 10px 8px 32px; border-radius: 8px; border: 1px solid var(--line); background: rgba(8, 13, 22, 0.75); backdrop-filter: blur(10px); color: var(--text); font: inherit; outline: none; }
.search input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(63, 208, 255, 0.15); }
#results { position: absolute; right: 0; top: 38px; width: 320px; max-height: 380px; overflow: auto; background: var(--panel-solid); border: 1px solid var(--line-strong); border-radius: 10px; box-shadow: 0 18px 50px rgba(0, 0, 0, 0.6); display: none; }
#results.open { display: block; }
#results button { display: flex; width: 100%; gap: 10px; align-items: center; text-align: left; padding: 8px 12px; border: 0; background: transparent; border-bottom: 1px solid rgba(130, 170, 235, 0.08); }
#results button:hover, #results button.act { background: rgba(63, 208, 255, 0.1); }
#results small { color: var(--muted); margin-left: auto; }

/* ------------------------------------------------------------------ panels */
aside { position: absolute; z-index: 10; top: calc(var(--top) + 4px); bottom: calc(var(--bottom) + 14px); overflow-y: auto; overflow-x: hidden; scrollbar-width: thin; scrollbar-color: rgba(130, 170, 235, 0.3) transparent; display: flex; flex-direction: column; gap: 10px; }
#left { left: 14px; width: var(--left); }
#right { right: 14px; width: var(--right); }
#right[hidden] { display: none; }
.card { background: var(--panel); backdrop-filter: blur(14px) saturate(1.3); border: 1px solid var(--line); border-radius: 12px; padding: 13px 14px; box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(180, 210, 255, 0.05); flex: none; }
.card h2 { font-size: 10.5px; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; color: var(--text-2); display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; gap: 8px; }
.card h2 .hint { font-weight: 500; letter-spacing: 0.04em; text-transform: none; color: var(--muted); font-size: 11px; }
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: 6px; overflow: hidden; letter-spacing: 0; text-transform: none; }
.seg button { border: 0; background: transparent; padding: 3px 8px; font-size: 11px; color: var(--muted); }
.seg button + button { border-left: 1px solid var(--line); }
.seg button.on { background: rgba(63, 208, 255, 0.18); color: #fff; }

/* big live counter */
.big { display: flex; align-items: baseline; gap: 10px; }
.big .n { font: 600 40px/1 var(--mono); letter-spacing: -0.04em; color: #fff; text-shadow: 0 0 24px rgba(63, 208, 255, 0.45); }
.big .l { color: var(--text-2); font-size: 12px; }
.stack { display: flex; height: 6px; border-radius: 3px; overflow: hidden; gap: 2px; margin: 10px 0 8px; background: rgba(130, 170, 235, 0.08); }
.stack i { display: block; height: 100%; transition: flex-basis 0.4s; min-width: 0; }
.cats { display: flex; flex-direction: column; gap: 3px; }
.cat { display: grid; grid-template-columns: 14px 1fr auto; align-items: center; gap: 9px; padding: 7px 8px; border-radius: 8px; border: 1px solid transparent; background: transparent; width: 100%; text-align: left; transition: background 0.15s, opacity 0.2s, border-color 0.15s; }
.cat:hover { background: rgba(130, 170, 235, 0.08); border-color: var(--line); }
.cat .sw { width: 11px; height: 11px; border-radius: 50%; background: var(--c); box-shadow: 0 0 10px var(--c); }
.cat .nm { font-weight: 600; }
.cat .nm small { display: block; font-weight: 400; color: var(--muted); font-size: 11px; }
.cat .v { text-align: right; font: 600 17px var(--mono); letter-spacing: -0.03em; }
.cat .v small { display: block; font: 400 10.5px var(--font); color: var(--muted); letter-spacing: 0; }
.cat.off { opacity: 0.38; }
.cat.off .sw { background: transparent; box-shadow: none; border: 1.5px solid var(--c); }
.tools { display: flex; gap: 6px; margin-top: 8px; flex-wrap: wrap; }
.chip { border: 1px solid var(--line); background: rgba(130, 170, 235, 0.06); border-radius: 999px; padding: 4px 10px; font-size: 11.5px; color: var(--text-2); }
.chip:hover { border-color: var(--line-strong); color: #fff; }
.chip.on { background: rgba(63, 208, 255, 0.18); border-color: rgba(63, 208, 255, 0.5); color: #fff; }

/* travel-time classes */
.bands { display: flex; flex-direction: column; gap: 5px; }
.band { display: grid; grid-template-columns: 12px 58px 1fr 46px; gap: 8px; align-items: center; font-size: 12px; }
.band .sw { width: 12px; height: 12px; border-radius: 3px; background: var(--c); box-shadow: 0 0 9px var(--c); }
.band .bar { height: 8px; border-radius: 4px; background: rgba(130, 170, 235, 0.08); overflow: hidden; }
.band .bar i { display: block; height: 100%; background: var(--c); border-radius: 4px; box-shadow: 0 0 10px var(--c); transition: width 0.35s; }
.band .c { text-align: right; font: 600 12px var(--mono); }
.origin { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; padding: 9px 10px; border-radius: 9px; background: rgba(255, 255, 255, 0.05); border: 1px solid var(--line); }
.origin .dot { width: 12px; height: 12px; border-radius: 50%; background: #fff; box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.2), 0 0 16px #fff; flex: none; }
.origin b { display: block; font-size: 14px; }
.origin small { color: var(--text-2); }
.note { color: var(--muted); font-size: 11.5px; margin-top: 9px; line-height: 1.45; }
.note b { color: var(--text-2); font-weight: 600; }

/* flow legend */
.grad { height: 10px; border-radius: 5px; margin: 6px 0 4px; box-shadow: 0 0 14px rgba(255, 120, 60, 0.25); }
.grad-l { display: flex; justify-content: space-between; font: 11px var(--mono); color: var(--text-2); }
.corr { margin-top: 10px; display: flex; flex-direction: column; gap: 1px; }
.corr button { display: grid; grid-template-columns: 1fr auto; gap: 10px; border: 0; background: transparent; text-align: left; padding: 5px 6px; border-radius: 6px; align-items: center; }
.corr button:hover { background: rgba(130, 170, 235, 0.1); }
.corr .nm { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 12px; }
.corr .nm small { color: var(--muted); margin-left: 6px; }
.corr .vv { font: 600 12px var(--mono); }
.corr .meter { grid-column: 1 / -1; height: 3px; border-radius: 2px; background: rgba(130, 170, 235, 0.08); overflow: hidden; }
.corr .meter i { display: block; height: 100%; border-radius: 2px; }

/* profile chart */
#profile { position: relative; }
#profile svg { display: block; width: 100%; height: 118px; overflow: visible; }
#profile .grid line { stroke: rgba(130, 170, 235, 0.1); stroke-width: 1; }
#profile .ax text { fill: var(--muted); font: 10px var(--mono); }
#profile .area { stroke: #0a111c; stroke-width: 1.5; }
#profile .head { stroke: #fff; stroke-width: 1.3; }
#profile .cross { stroke: rgba(255, 255, 255, 0.55); stroke-width: 1; stroke-dasharray: 3 3; }
#ptip { position: absolute; pointer-events: none; z-index: 5; background: var(--panel-solid); border: 1px solid var(--line-strong); border-radius: 8px; padding: 7px 9px; font-size: 11.5px; display: none; white-space: nowrap; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5); }
#ptip .r { display: flex; gap: 8px; align-items: center; justify-content: space-between; }
#ptip .r i { width: 8px; height: 8px; border-radius: 2px; display: inline-block; }
#ptip b { font-family: var(--mono); margin-left: 12px; }

/* busiest stations */
#busy { display: flex; flex-direction: column; gap: 2px; }
#busy button { display: grid; grid-template-columns: 18px 1fr auto; gap: 8px; width: 100%; border: 0; background: transparent; text-align: left; padding: 4px 4px; border-radius: 6px; align-items: center; }
#busy button:hover { background: rgba(130, 170, 235, 0.1); }
#busy .rk { font: 11px var(--mono); color: var(--muted); }
#busy .nm { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#busy .v { font: 600 12px var(--mono); }
#busy .m { grid-column: 2 / 4; display: flex; height: 3px; gap: 1px; border-radius: 2px; overflow: hidden; background: rgba(130, 170, 235, 0.07); }
#busy .m i { display: block; height: 100%; }

/* ------------------------------------------------------------------ details panel */
#right .card { padding: 0; overflow: hidden; }
.dh { padding: 14px 14px 12px; border-bottom: 1px solid var(--line); position: relative; background: linear-gradient(180deg, color-mix(in srgb, var(--c, #3fd0ff) 14%, transparent), transparent); }
.dh .x { position: absolute; right: 8px; top: 8px; width: 26px; height: 26px; border-radius: 6px; border: 1px solid var(--line); background: rgba(130, 170, 235, 0.06); color: var(--text-2); font-size: 15px; line-height: 1; }
.dh .x:hover { color: #fff; border-color: var(--line-strong); }
.badge { display: inline-flex; align-items: center; gap: 7px; padding: 3px 9px 3px 7px; border-radius: 999px; font-weight: 700; font-size: 11.5px; letter-spacing: 0.04em; background: color-mix(in srgb, var(--c) 18%, transparent); border: 1px solid color-mix(in srgb, var(--c) 55%, transparent); color: #fff; }
.badge i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); box-shadow: 0 0 8px var(--c); }
.dh h3 { font-size: 16px; line-height: 1.25; margin: 9px 26px 3px 0; font-weight: 700; }
.dh .sub { color: var(--text-2); font-size: 12px; }
.kv { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line); border-bottom: 1px solid var(--line); }
.kv div { background: rgba(8, 13, 22, 0.9); padding: 8px 12px; }
.kv small { display: block; color: var(--muted); font-size: 10.5px; letter-spacing: 0.08em; text-transform: uppercase; }
.kv b { font: 600 14px var(--mono); letter-spacing: -0.02em; }
.progress { padding: 11px 14px; border-bottom: 1px solid var(--line); }
.progress .pt { display: flex; justify-content: space-between; font-size: 12px; margin-bottom: 7px; gap: 8px; }
.progress .pb { height: 5px; border-radius: 3px; background: rgba(130, 170, 235, 0.12); overflow: hidden; }
.progress .pb i { display: block; height: 100%; background: var(--c); box-shadow: 0 0 10px var(--c); width: 0; }
.actions { display: flex; gap: 6px; padding: 10px 14px; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.tt { max-height: calc(100vh - var(--top) - var(--bottom) - 330px); min-height: 160px; overflow-y: auto; scrollbar-width: thin; scrollbar-color: rgba(130, 170, 235, 0.3) transparent; padding: 6px 0 10px; position: relative; }
.stop { display: grid; grid-template-columns: 62px 18px 1fr; align-items: stretch; padding: 0 14px 0 8px; position: relative; cursor: default; }
.stop .tm { text-align: right; padding: 7px 4px 7px 0; font: 12px var(--mono); color: var(--text-2); line-height: 1.25; }
.stop .tm b { color: #fff; font-weight: 600; display: block; }
.stop .tm s { text-decoration: none; color: var(--muted); display: block; }
.stop .rail { position: relative; }
.stop .rail::before { content: ""; position: absolute; left: 8px; top: 0; bottom: 0; width: 2px; background: color-mix(in srgb, var(--c) 55%, transparent); }
.stop:first-child .rail::before { top: 14px; }
.stop:last-child .rail::before { bottom: calc(100% - 14px); }
.stop.done .rail::before { background: rgba(160, 180, 215, 0.3); }
.stop .rail::after { content: ""; position: absolute; left: 4px; top: 10px; width: 10px; height: 10px; border-radius: 50%; background: var(--panel-solid); border: 2px solid var(--c); }
.stop.done .rail::after { border-color: rgba(160, 180, 215, 0.55); }
.stop.pass .rail::after { width: 6px; height: 6px; left: 6px; top: 12px; border-width: 1.5px; opacity: 0.6; }
.stop.cur .rail::after { background: var(--c); box-shadow: 0 0 0 4px color-mix(in srgb, var(--c) 30%, transparent), 0 0 14px var(--c); }
.stop.end .rail::after { background: var(--c); }
.stop .nm { padding: 6px 0 6px 6px; border-radius: 6px; min-width: 0; }
.stop .nm button.st { border: 0; background: none; padding: 0; text-align: left; font-weight: 600; font-size: 13px; color: var(--text); display: block; }
.stop .nm button.st:hover { color: #fff; text-decoration: underline; text-decoration-color: var(--accent); }
.stop.pass .nm button.st { font-weight: 400; color: var(--muted); }
.stop.done .nm button.st { color: var(--text-2); }
.stop .nm .meta { color: var(--muted); font-size: 11px; }
.conn-btn { margin-top: 3px; border: 1px solid var(--line); background: rgba(130, 170, 235, 0.06); border-radius: 999px; padding: 1px 8px; font-size: 11px; color: var(--text-2); }
.conn-btn:hover { border-color: var(--line-strong); color: #fff; }
.conn-btn.open { border-color: var(--accent); color: #fff; }
.conns { margin: 5px 0 4px; display: flex; flex-direction: column; gap: 2px; }
.conns button { display: grid; grid-template-columns: 44px 10px 1fr auto; gap: 7px; align-items: center; border: 0; background: rgba(130, 170, 235, 0.06); padding: 4px 7px; border-radius: 6px; text-align: left; font-size: 11.5px; }
.conns button:hover { background: rgba(130, 170, 235, 0.14); }
.conns .t { font: 12px var(--mono); color: #fff; }
.conns .d { width: 8px; height: 8px; border-radius: 50%; background: var(--c); box-shadow: 0 0 6px var(--c); }
.conns .w { color: var(--muted); font: 11px var(--mono); }
.conns span.l { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* station panel */
.hist { display: flex; align-items: flex-end; gap: 2px; height: 46px; padding: 10px 14px 0; }
.hist i { flex: 1; min-width: 0; border-radius: 2px 2px 0 0; background: rgba(160, 190, 240, 0.35); position: relative; }
.hist i.now { background: #fff; box-shadow: 0 0 8px #fff; }
.hist-l { display: flex; justify-content: space-between; padding: 3px 14px 8px; font: 10px var(--mono); color: var(--muted); border-bottom: 1px solid var(--line); }
.tabs { display: flex; padding: 8px 14px 0; gap: 4px; }
.tabs button { border: 0; background: transparent; padding: 6px 10px; border-radius: 6px 6px 0 0; color: var(--muted); font-weight: 600; border-bottom: 2px solid transparent; }
.tabs button.on { color: #fff; border-bottom-color: var(--accent); }
.board { max-height: calc(100vh - var(--top) - var(--bottom) - 440px); min-height: 150px; overflow-y: auto; padding: 4px 8px 10px; scrollbar-width: thin; scrollbar-color: rgba(130, 170, 235, 0.3) transparent; }
.board button { display: grid; grid-template-columns: 44px 10px 1fr; gap: 8px; width: 100%; align-items: center; border: 0; background: transparent; padding: 6px 6px; border-radius: 7px; text-align: left; }
.board button:hover { background: rgba(130, 170, 235, 0.1); }
.board .t { font: 600 13px var(--mono); }
.board .d { width: 9px; height: 9px; border-radius: 50%; background: var(--c); box-shadow: 0 0 7px var(--c); }
.board .to { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.board .to small { display: block; color: var(--muted); font-size: 11px; }
.board .past { opacity: 0.4; }
.board .sep { text-align: center; color: var(--accent); font-size: 10.5px; letter-spacing: 0.14em; text-transform: uppercase; padding: 6px 0; border-top: 1px dashed rgba(63, 208, 255, 0.4); margin-top: 4px; }

/* journey in tooltip / panel */
.jr { display: flex; flex-direction: column; gap: 4px; margin-top: 6px; }
.jr div { display: grid; grid-template-columns: 44px 1fr; gap: 8px; font-size: 11.5px; }
.jr .t { font: 11.5px var(--mono); color: var(--text-2); }
.jr .w { color: var(--muted); }

/* ------------------------------------------------------------------ tooltip */
#tooltip { position: absolute; z-index: 30; pointer-events: none; display: none; max-width: 320px; background: rgba(8, 13, 22, 0.94); border: 1px solid var(--line-strong); border-radius: 10px; padding: 9px 11px; box-shadow: 0 14px 40px rgba(0, 0, 0, 0.6); backdrop-filter: blur(10px); }
#tooltip .h { display: flex; align-items: center; gap: 8px; font-weight: 700; }
#tooltip .h i { width: 9px; height: 9px; border-radius: 50%; background: var(--c); box-shadow: 0 0 8px var(--c); flex: none; }
#tooltip .s { color: var(--text-2); font-size: 12px; margin-top: 2px; }
#tooltip .big2 { font: 600 20px var(--mono); letter-spacing: -0.03em; margin-top: 3px; }

/* ------------------------------------------------------------------ zoom + hint */
#zoom { position: absolute; right: 14px; bottom: calc(var(--bottom) + 18px); z-index: 12; display: flex; flex-direction: column; gap: 4px; transition: right 0.25s; }
#app.has-right #zoom { right: calc(var(--right) + 28px); }
#zoom button { width: 34px; height: 34px; border-radius: 8px; border: 1px solid var(--line); background: var(--panel); backdrop-filter: blur(10px); font-size: 18px; color: var(--text-2); display: grid; place-items: center; }
#zoom button:hover { color: #fff; border-color: var(--line-strong); }
#zoom svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 1.6; }
#hint { position: absolute; z-index: 11; left: 50%; top: calc(var(--top) + 8px); transform: translateX(-50%); padding: 8px 16px; border-radius: 999px; background: rgba(8, 13, 22, 0.8); border: 1px solid var(--line-strong); backdrop-filter: blur(10px); color: var(--text); font-size: 12.5px; opacity: 0; transition: opacity 0.35s; pointer-events: none; white-space: nowrap; margin-left: calc((var(--left) - var(--right)) / 2); }
#hint.on { opacity: 1; }
#hint b { color: var(--accent); }

/* ------------------------------------------------------------------ timeline */
#timeline { position: absolute; left: 14px; right: 14px; bottom: 14px; height: var(--bottom); z-index: 15; display: grid; grid-template-columns: auto auto 1fr auto; align-items: center; gap: 16px; padding: 0 18px 0 14px; background: var(--panel); border: 1px solid var(--line); border-radius: 14px; backdrop-filter: blur(16px) saturate(1.3); box-shadow: 0 10px 40px rgba(0, 0, 0, 0.4); }
#play { width: 46px; height: 46px; border-radius: 50%; border: 1px solid rgba(63, 208, 255, 0.55); background: radial-gradient(circle at 50% 35%, rgba(63, 208, 255, 0.3), rgba(63, 208, 255, 0.06)); display: grid; place-items: center; box-shadow: 0 0 22px rgba(63, 208, 255, 0.25); }
#play:hover { box-shadow: 0 0 30px rgba(63, 208, 255, 0.5); }
#play svg { width: 18px; height: 18px; fill: #fff; }
.clock { font-family: var(--mono); display: flex; align-items: baseline; min-width: 128px; }
#clock { font-size: 36px; font-weight: 600; letter-spacing: -0.05em; color: #fff; text-shadow: 0 0 22px rgba(63, 208, 255, 0.5); }
#clockSec { font-size: 17px; color: var(--muted); margin-left: 2px; }
.scrub-wrap { min-width: 0; padding-top: 6px; }
#scrub { position: relative; height: 46px; cursor: ew-resize; border-radius: 6px; outline: none; touch-action: none; }
#scrub:focus-visible { box-shadow: 0 0 0 2px rgba(63, 208, 255, 0.5); }
#scrubCanvas { position: absolute; inset: 0; width: 100%; height: 100%; }
#scrubHead { position: absolute; top: -2px; bottom: 12px; width: 2px; background: #fff; box-shadow: 0 0 12px #fff, 0 0 3px #fff; border-radius: 1px; pointer-events: none; }
#scrubHead::before { content: ""; position: absolute; left: -5px; top: -1px; border: 6px solid transparent; border-top-color: #fff; border-bottom: 0; }
#scrubTip { position: absolute; bottom: calc(100% + 6px); transform: translateX(-50%); padding: 2px 7px; border-radius: 5px; background: var(--panel-solid); border: 1px solid var(--line-strong); font: 11px var(--mono); display: none; pointer-events: none; }
#speeds { display: flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
#speeds button { border: 0; background: transparent; padding: 7px 9px; color: var(--muted); font: 600 11.5px var(--mono); }
#speeds button + button { border-left: 1px solid var(--line); }
#speeds button:hover { color: #fff; }
#speeds button.on { background: rgba(63, 208, 255, 0.2); color: #fff; }

/* ------------------------------------------------------------------ loader */
#loader { position: absolute; inset: 0; z-index: 100; background: #04070d; display: grid; place-content: center; justify-items: center; gap: 18px; transition: opacity 0.7s, visibility 0.7s; }
#loader.done { opacity: 0; visibility: hidden; }
#loader .ring { width: 54px; height: 54px; border-radius: 50%; border: 2px solid rgba(63, 208, 255, 0.2); border-top-color: var(--accent); animation: spin 1s linear infinite; }
#loader p { color: var(--text-2); letter-spacing: 0.1em; text-transform: uppercase; font-size: 11.5px; }
#loader .bar { width: 240px; height: 3px; background: rgba(130, 170, 235, 0.15); border-radius: 2px; overflow: hidden; }
#loader .bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--tgv), var(--ic), var(--ter)); transition: width 0.2s; }

@media (max-width: 1180px) {
  :root { --left: 296px; --right: 340px; }
  .brand p, #modes button b { display: none; }
  .search input { width: 160px; }
}
@media (max-width: 900px) {
  #left { display: none; }
  #speeds, .brand-txt p { display: none; }
  #hint { margin-left: 0; }
}

tool_response.content:
:root {
  --bg: #050910;
  --panel: rgba(9, 15, 26, 0.76);
  --panel-solid: #0a111c;
  --line: rgba(130, 170, 235, 0.16);
  --line-strong: rgba(150, 190, 255, 0.3);
  --text: #dbe6f7;
  --text-2: #9db0cc;
  --muted: #6b7f9e;
  --accent: #3fd0ff;
  --tgv: #ff4d94;
  --ic: #ffb020;
  --ter: #3fd0ff;
  --font: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
  --left: 336px;
  --right: 372px;
  --top: 58px;
  --bottom: 76px;
}
* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; background: var(--bg); color: var(--text); font: 13px/1.4 var(--font); overflow: hidden; -webkit-font-smoothing: antialiased; }
button { font: inherit; color: inherit; cursor: pointer; }
h1, h2, h3, p, ol, ul { margin: 0; padding: 0; }
ol, ul { list-style: none; }
.num { font-variant-numeric: tabular-nums; font-family: var(--mono); letter-spacing: -0.02em; }

#app { position: fixed; inset: 0; }
#stage { position: absolute; inset: 0; background:
  radial-gradient(1200px 800px at 55% 45%, #0e1a2e 0%, #08111f 45%, #04070d 100%); cursor: grab; touch-action: none; }
#stage.drag { cursor: grabbing; }
#stage.pointer { cursor: pointer; }
#stage canvas { position: absolute; left: 0; top: 0; }
#night { position: absolute; inset: 0; pointer-events: none; background: #04123a; opacity: 0; mix-blend-mode: multiply; }
#vignette { position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse at 52% 48%, transparent 52%, rgba(2, 4, 9, 0.62) 100%),
    repeating-linear-gradient(0deg, rgba(120, 170, 255, 0.018) 0 1px, transparent 1px 3px); }

/* ------------------------------------------------------------------ header */
#top { position: absolute; left: 0; right: 0; top: 0; height: var(--top); display: flex; align-items: center; justify-content: space-between; padding: 0 16px; gap: 16px;
  background: linear-gradient(180deg, rgba(5, 9, 16, 0.92), rgba(5, 9, 16, 0.55) 70%, transparent); z-index: 20; pointer-events: none; }
#top > * { pointer-events: auto; }
#top::after { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 2px; background: linear-gradient(90deg, var(--tgv), var(--ic) 50%, var(--ter)); opacity: 0.8; pointer-events: none; }
.brand { display: flex; align-items: center; gap: 12px; min-width: 250px; }
.logo { position: relative; width: 30px; height: 30px; }
.logo i { position: absolute; inset: 0; border-radius: 50%; border: 1.5px solid; opacity: 0.9; }
.logo i:nth-child(1) { border-color: var(--tgv); inset: 0; animation: spin 14s linear infinite; border-right-color: transparent; }
.logo i:nth-child(2) { border-color: var(--ic); inset: 5px; animation: spin 9s linear infinite reverse; border-bottom-color: transparent; }
.logo i:nth-child(3) { border-color: var(--ter); inset: 10px; background: var(--ter); box-shadow: 0 0 12px var(--ter); }
@keyframes spin { to { transform: rotate(360deg); } }
.brand h1 { font-size: 15px; font-weight: 700; letter-spacing: 0.22em; text-transform: uppercase; }
.brand p { font-size: 10.5px; letter-spacing: 0.14em; color: var(--muted); text-transform: uppercase; margin-top: 1px; }

#modes { display: flex; gap: 4px; padding: 3px; border: 1px solid var(--line); border-radius: 10px; background: rgba(8, 13, 22, 0.7); backdrop-filter: blur(10px); }
#modes button { border: 0; background: transparent; color: var(--text-2); padding: 7px 14px; border-radius: 7px; font-weight: 600; letter-spacing: 0.04em; display: flex; gap: 8px; align-items: center; transition: background 0.2s, color 0.2s; }
#modes button b { font: 600 10px var(--mono); color: var(--muted); }
#modes button:hover { color: #fff; background: rgba(120, 160, 230, 0.1); }
#modes button.on { color: #04101c; background: linear-gradient(180deg, #7fe0ff, #3fd0ff); box-shadow: 0 0 18px rgba(63, 208, 255, 0.4); }
#modes button.on b { color: rgba(4, 16, 28, 0.6); }
.top-right { display: flex; gap: 10px; align-items: center; min-width: 250px; justify-content: flex-end; }
#days { display: flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; background: rgba(8, 13, 22, 0.7); backdrop-filter: blur(10px); }
#days button { border: 0; background: transparent; padding: 7px 11px; color: var(--text-2); font-size: 12px; }
#days button + button { border-left: 1px solid var(--line); }
#days button.on { background: rgba(63, 208, 255, 0.16); color: #fff; }
.search { position: relative; }
.search svg { position: absolute; left: 10px; top: 9px; width: 15px; height: 15px; stroke: var(--muted); fill: none; stroke-width: 1.6; pointer-events: none; }
.search input { width: 230px; padding: 8px 10px 8px 32px; border-radius: 8px; border: 1px solid var(--line); background: rgba(8, 13, 22, 0.75); backdrop-filter: blur(10px); color: var(--text); font: inherit; outline: none; }
.search input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(63, 208, 255, 0.15); }
#results { position: absolute; right: 0; top: 38px; width: 320px; max-height: 380px; overflow: auto; background: var(--panel-solid); border: 1px solid var(--line-strong); border-radius: 10px; box-shadow: 0 18px 50px rgba(0, 0, 0, 0.6); display: none; }
#results.open { display: block; }
#results button { display: flex; width: 100%; gap: 10px; align-items: center; text-align: left; padding: 8px 12px; border: 0; background: transparent; border-bottom: 1px solid rgba(130, 170, 235, 0.08); }
#results button:hover, #results button.act { background: rgba(63, 208, 255, 0.1); }
#results small { color: var(--muted); margin-left: auto; }

/* ------------------------------------------------------------------ panels */
aside { position: absolute; z-index: 10; top: calc(var(--top) + 4px); bottom: calc(var(--bottom) + 14px); overflow-y: auto; overflow-x: hidden; scrollbar-width: thin; scrollbar-color: rgba(130, 170, 235, 0.3) transparent; display: flex; flex-direction: column; gap: 10px; }
#left { left: 14px; width: var(--left); }
#right { right: 14px; width: var(--right); }
#right[hidden] { display: none; }
.card { background: var(--panel); backdrop-filter: blur(14px) saturate(1.3); border: 1px solid var(--line); border-radius: 12px; padding: 13px 14px; box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(180, 210, 255, 0.05); flex: none; }
.card h2 { font-size: 10.5px; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; color: var(--text-2); display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; gap: 8px; }
.card h2 .hint { font-weight: 500; letter-spacing: 0.04em; text-transform: none; color: var(--muted); font-size: 11px; }
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: 6px; overflow: hidden; letter-spacing: 0; text-transform: none; }
.seg button { border: 0; background: transparent; padding: 3px 8px; font-size: 11px; color: var(--muted); }
.seg button + button { border-left: 1px solid var(--line); }
.seg button.on { background: rgba(63, 208, 255, 0.18); color: #fff; }

/* big live counter */
.big { display: flex; align-items: baseline; gap: 10px; }
.big .n { font: 600 40px/1 var(--mono); letter-spacing: -0.04em; color: #fff; text-shadow: 0 0 24px rgba(63, 208, 255, 0.45); }
.big .l { color: var(--text-2); font-size: 12px; }
.stack { display: flex; height: 6px; border-radius: 3px; overflow: hidden; gap: 2px; margin: 10px 0 8px; background: rgba(130, 170, 235, 0.08); }
.stack i { display: block; height: 100%; transition: flex-basis 0.4s; min-width: 0; }
.cats { display: flex; flex-direction: column; gap: 3px; }
.cat { display: grid; grid-template-columns: 14px 1fr auto; align-items: center; gap: 9px; padding: 7px 8px; border-radius: 8px; border: 1px solid transparent; background: transparent; width: 100%; text-align: left; transition: background 0.15s, opacity 0.2s, border-color 0.15s; }
.cat:hover { background: rgba(130, 170, 235, 0.08); border-color: var(--line); }
.cat .sw { width: 11px; height: 11px; border-radius: 50%; background: var(--c); box-shadow: 0 0 10px var(--c); }
.cat .nm { font-weight: 600; }
.cat .nm small { display: block; font-weight: 400; color: var(--muted); font-size: 11px; }
.cat .v { text-align: right; font: 600 17px var(--mono); letter-spacing: -0.03em; }
.cat .v small { display: block; font: 400 10.5px var(--font); color: var(--muted); letter-spacing: 0; }
.cat.off { opacity: 0.38; }
.cat.off .sw { background: transparent; box-shadow: none; border: 1.5px solid var(--c); }
.tools { display: flex; gap: 6px; margin-top: 8px; flex-wrap: wrap; }
.chip { border: 1px solid var(--line); background: rgba(130, 170, 235, 0.06); border-radius: 999px; padding: 4px 10px; font-size: 11.5px; color: var(--text-2); }
.chip:hover { border-color: var(--line-strong); color: #fff; }
.chip.on { background: rgba(63, 208, 255, 0.18); border-color: rgba(63, 208, 255, 0.5); color: #fff; }

/* travel-time classes */
.bands { display: flex; flex-direction: column; gap: 5px; }
.band { display: grid; grid-template-columns: 12px 58px 1fr 46px; gap: 8px; align-items: center; font-size: 12px; }
.band .sw { width: 12px; height: 12px; border-radius: 3px; background: var(--c); box-shadow: 0 0 9px var(--c); }
.band .bar { height: 8px; border-radius: 4px; background: rgba(130, 170, 235, 0.08); overflow: hidden; }
.band .bar i { display: block; height: 100%; background: var(--c); border-radius: 4px; box-shadow: 0 0 10px var(--c); transition: width 0.35s; }
.band .c { text-align: right; font: 600 12px var(--mono); }
.origin { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; padding: 9px 10px; border-radius: 9px; background: rgba(255, 255, 255, 0.05); border: 1px solid var(--line); }
.origin .dot { width: 12px; height: 12px; border-radius: 50%; background: #fff; box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.2), 0 0 16px #fff; flex: none; }
.origin b { display: block; font-size: 14px; }
.origin small { color: var(--text-2); }
.note { color: var(--muted); font-size: 11.5px; margin-top: 9px; line-height: 1.45; }
.note b { color: var(--text-2); font-weight: 600; }

/* flow legend */
.grad { height: 10px; border-radius: 5px; margin: 6px 0 4px; box-shadow: 0 0 14px rgba(255, 120, 60, 0.25); }
.grad-l { display: flex; justify-content: space-between; font: 11px var(--mono); color: var(--text-2); }
.corr { margin-top: 10px; display: flex; flex-direction: column; gap: 1px; }
.corr button { display: grid; grid-template-columns: 1fr auto; gap: 10px; border: 0; background: transparent; text-align: left; padding: 5px 6px; border-radius: 6px; align-items: center; }
.corr button:hover { background: rgba(130, 170, 235, 0.1); }
.corr .nm { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 12px; }
.corr .nm small { color: var(--muted); margin-left: 6px; }
.corr .vv { font: 600 12px var(--mono); }
.corr .meter { grid-column: 1 / -1; height: 3px; border-radius: 2px; background: rgba(130, 170, 235, 0.08); overflow: hidden; }
.corr .meter i { display: block; height: 100%; border-radius: 2px; }

/* profile chart */
#profile { position: relative; }
#profile svg { display: block; width: 100%; height: 118px; overflow: visible; }
#profile .grid line { stroke: rgba(130, 170, 235, 0.1); stroke-width: 1; }
#profile .ax text { fill: var(--muted); font: 10px var(--mono); }
#profile .area { stroke: #0a111c; stroke-width: 1.5; }
#profile .head { stroke: #fff; stroke-width: 1.3; }
#profile .cross { stroke: rgba(255, 255, 255, 0.55); stroke-width: 1; stroke-dasharray: 3 3; }
#ptip { position: absolute; pointer-events: none; z-index: 5; background: var(--panel-solid); border: 1px solid var(--line-strong); border-radius: 8px; padding: 7px 9px; font-size: 11.5px; display: none; white-space: nowrap; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5); }
#ptip .r { display: flex; gap: 8px; align-items: center; justify-content: space-between; }
#ptip .r i { width: 8px; height: 8px; border-radius: 2px; display: inline-block; }
#ptip b { font-family: var(--mono); margin-left: 12px; }

/* busiest stations */
#busy { display: flex; flex-direction: column; gap: 2px; }
#busy button { display: grid; grid-template-columns: 18px 1fr auto; gap: 8px; width: 100%; border: 0; background: transparent; text-align: left; padding: 4px 4px; border-radius: 6px; align-items: center; }
#busy button:hover { background: rgba(130, 170, 235, 0.1); }
#busy .rk { font: 11px var(--mono); color: var(--muted); }
#busy .nm { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#busy .v { font: 600 12px var(--mono); }
#busy .m { grid-column: 2 / 4; display: flex; height: 3px; gap: 1px; border-radius: 2px; overflow: hidden; background: rgba(130, 170, 235, 0.07); }
#busy .m i { display: block; height: 100%; }

/* ------------------------------------------------------------------ details panel */
#right .card { padding: 0; overflow: hidden; }
.dh { padding: 14px 14px 12px; border-bottom: 1px solid var(--line); position: relative; background: linear-gradient(180deg, color-mix(in srgb, var(--c, #3fd0ff) 14%, transparent), transparent); }
.dh .x { position: absolute; right: 8px; top: 8px; width: 26px; height: 26px; border-radius: 6px; border: 1px solid var(--line); background: rgba(130, 170, 235, 0.06); color: var(--text-2); font-size: 15px; line-height: 1; }
.dh .x:hover { color: #fff; border-color: var(--line-strong); }
.badge { display: inline-flex; align-items: center; gap: 7px; padding: 3px 9px 3px 7px; border-radius: 999px; font-weight: 700; font-size: 11.5px; letter-spacing: 0.04em; background: color-mix(in srgb, var(--c) 18%, transparent); border: 1px solid color-mix(in srgb, var(--c) 55%, transparent); color: #fff; }
.badge i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); box-shadow: 0 0 8px var(--c); }
.dh h3 { font-size: 16px; line-height: 1.25; margin: 9px 26px 3px 0; font-weight: 700; }
.dh .sub { color: var(--text-2); font-size: 12px; }
.kv { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line); border-bottom: 1px solid var(--line); }
.kv div { background: rgba(8, 13, 22, 0.9); padding: 8px 12px; }
.kv small { display: block; color: var(--muted); font-size: 10.5px; letter-spacing: 0.08em; text-transform: uppercase; }
.kv b { font: 600 14px var(--mono); letter-spacing: -0.02em; }
.progress { padding: 11px 14px; border-bottom: 1px solid var(--line); }
.progress .pt { display: flex; justify-content: space-between; font-size: 12px; margin-bottom: 7px; gap: 8px; }
.progress .pb { height: 5px; border-radius: 3px; background: rgba(130, 170, 235, 0.12); overflow: hidden; }
.progress .pb i { display: block; height: 100%; background: var(--c); box-shadow: 0 0 10px var(--c); width: 0; }
.actions { display: flex; gap: 6px; padding: 10px 14px; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.tt { max-height: calc(100vh - var(--top) - var(--bottom) - 330px); min-height: 160px; overflow-y: auto; scrollbar-width: thin; scrollbar-color: rgba(130, 170, 235, 0.3) transparent; padding: 6px 0 10px; position: relative; }
.stop { display: grid; grid-template-columns: 62px 18px 1fr; align-items: stretch; padding: 0 14px 0 8px; position: relative; cursor: default; }
.stop .tm { text-align: right; padding: 7px 4px 7px 0; font: 12px var(--mono); color: var(--text-2); line-height: 1.25; }
.stop .tm b { color: #fff; font-weight: 600; display: block; }
.stop .tm s { text-decoration: none; color: var(--muted); display: block; }
.stop .rail { position: relative; }
.stop .rail::before { content: ""; position: absolute; left: 8px; top: 0; bottom: 0; width: 2px; background: color-mix(in srgb, var(--c) 55%, transparent); }
.stop:first-child .rail::before { top: 14px; }
.stop:last-child .rail::before { bottom: calc(100% - 14px); }
.stop.done .rail::before { background: rgba(160, 180, 215, 0.3); }
.stop .rail::after { content: ""; position: absolute; left: 4px; top: 10px; width: 10px; height: 10px; border-radius: 50%; background: var(--panel-solid); border: 2px solid var(--c); }
.stop.done .rail::after { border-color: rgba(160, 180, 215, 0.55); }
.stop.pass .rail::after { width: 6px; height: 6px; left: 6px; top: 12px; border-width: 1.5px; opacity: 0.6; }
.stop.cur .rail::after { background: var(--c); box-shadow: 0 0 0 4px color-mix(in srgb, var(--c) 30%, transparent), 0 0 14px var(--c); }
.stop.end .rail::after { background: var(--c); }
.stop .nm { padding: 6px 0 6px 6px; border-radius: 6px; min-width: 0; }
.stop .nm button.st { border: 0; background: none; padding: 0; text-align: left; font-weight: 600; font-size: 13px; color: var(--text); display: block; }
.stop .nm button.st:hover { color: #fff; text-decoration: underline; text-decoration-color: var(--accent); }
.stop.pass .nm button.st { font-weight: 400; color: var(--muted); }
.stop.done .nm button.st { color: var(--text-2); }
.stop .nm .meta { color: var(--muted); font-size: 11px; }
.conn-btn { margin-top: 3px; border: 1px solid var(--line); background: rgba(130, 170, 235, 0.06); border-radius: 999px; padding: 1px 8px; font-size: 11px; color: var(--text-2); }
.conn-btn:hover { border-color: var(--line-strong); color: #fff; }
.conn-btn.open { border-color: var(--accent); color: #fff; }
.conns { margin: 5px 0 4px; display: flex; flex-direction: column; gap: 2px; }
.conns button { display: grid; grid-template-columns: 44px 10px 1fr auto; gap: 7px; align-items: center; border: 0; background: rgba(130, 170, 235, 0.06); padding: 4px 7px; border-radius: 6px; text-align: left; font-size: 11.5px; }
.conns button:hover { background: rgba(130, 170, 235, 0.14); }
.conns .t { font: 12px var(--mono); color: #fff; }
.conns .d { width: 8px; height: 8px; border-radius: 50%; background: var(--c); box-shadow: 0 0 6px var(--c); }
.conns .w { color: var(--muted); font: 11px var(--mono); }
.conns span.l { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* station panel */
.hist { display: flex; align-items: flex-end; gap: 2px; height: 46px; padding: 10px 14px 0; }
.hist i { flex: 1; min-width: 0; border-radius: 2px 2px 0 0; background: rgba(160, 190, 240, 0.35); position: relative; }
.hist i.now { background: #fff; box-shadow: 0 0 8px #fff; }
.hist-l { display: flex; justify-content: space-between; padding: 3px 14px 8px; font: 10px var(--mono); color: var(--muted); border-bottom: 1px solid var(--line); }
.tabs { display: flex; padding: 8px 14px 0; gap: 4px; }
.tabs button { border: 0; background: transparent; padding: 6px 10px; border-radius: 6px 6px 0 0; color: var(--muted); font-weight: 600; border-bottom: 2px solid transparent; }
.tabs button.on { color: #fff; border-bottom-color: var(--accent); }
.board { max-height: calc(100vh - var(--top) - var(--bottom) - 440px); min-height: 150px; overflow-y: auto; padding: 4px 8px 10px; scrollbar-width: thin; scrollbar-color: rgba(130, 170, 235, 0.3) transparent; }
.board button { display: grid; grid-template-columns: 44px 10px 1fr; gap: 8px; width: 100%; align-items: center; border: 0; background: transparent; padding: 6px 6px; border-radius: 7px; text-align: left; }
.board button:hover { background: rgba(130, 170, 235, 0.1); }
.board .t { font: 600 13px var(--mono); }
.board .d { width: 9px; height: 9px; border-radius: 50%; background: var(--c); box-shadow: 0 0 7px var(--c); }
.board .to { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.board .to small { display: block; color: var(--muted); font-size: 11px; }
.board .past { opacity: 0.4; }
.board .sep { text-align: center; color: var(--accent); font-size: 10.5px; letter-spacing: 0.14em; text-transform: uppercase; padding: 6px 0; border-top: 1px dashed rgba(63, 208, 255, 0.4); margin-top: 4px; }

/* journey in tooltip / panel */
.jr { display: flex; flex-direction: column; gap: 4px; margin-top: 6px; }
.jr div { display: grid; grid-template-columns: 44px 1fr; gap: 8px; font-size: 11.5px; }
.jr .t { font: 11.5px var(--mono); color: var(--text-2); }
.jr .w { color: var(--muted); }

/* ------------------------------------------------------------------ tooltip */
#tooltip { position: absolute; z-index: 30; pointer-events: none; display: none; max-width: 320px; background: rgba(8, 13, 22, 0.94); border: 1px solid var(--line-strong); border-radius: 10px; padding: 9px 11px; box-shadow: 0 14px 40px rgba(0, 0, 0, 0.6); backdrop-filter: blur(10px); }
#tooltip .h { display: flex; align-items: center; gap: 8px; font-weight: 700; }
#tooltip .h i { width: 9px; height: 9px; border-radius: 50%; background: var(--c); box-shadow: 0 0 8px var(--c); flex: none; }
#tooltip .s { color: var(--text-2); font-size: 12px; margin-top: 2px; }
#tooltip .big2 { font: 600 20px var(--mono); letter-spacing: -0.03em; margin-top: 3px; }

/* ------------------------------------------------------------------ zoom + hint */
#zoom { position: absolute; right: 14px; bottom: calc(var(--bottom) + 18px); z-index: 12; display: flex; flex-direction: column; gap: 4px; transition: right 0.25s; }
#app.has-right #zoom { right: calc(var(--right) + 28px); }
#zoom button { width: 34px; height: 34px; border-radius: 8px; border: 1px solid var(--line); background: var(--panel); backdrop-filter: blur(10px); font-size: 18px; color: var(--text-2); display: grid; place-items: center; }
#zoom button:hover { color: #fff; border-color: var(--line-strong); }
#zoom svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 1.6; }
#hint { position: absolute; z-index: 11; left: 50%; top: calc(var(--top) + 8px); transform: translateX(-50%); padding: 8px 16px; border-radius: 999px; background: rgba(8, 13, 22, 0.8); border: 1px solid var(--line-strong); backdrop-filter: blur(10px); color: var(--text); font-size: 12.5px; opacity: 0; transition: opacity 0.35s; pointer-events: none; white-space: nowrap; margin-left: calc((var(--left) - var(--right)) / 2); }
#hint.on { opacity: 1; }
#hint b { color: var(--accent); }

/* ------------------------------------------------------------------ timeline */
#timeline { position: absolute; left: 14px; right: 14px; bottom: 14px; height: var(--bottom); z-index: 15; display: grid; grid-template-columns: auto auto 1fr auto; align-items: center; gap: 16px; padding: 0 18px 0 14px; background: var(--panel); border: 1px solid var(--line); border-radius: 14px; backdrop-filter: blur(16px) saturate(1.3); box-shadow: 0 10px 40px rgba(0, 0, 0, 0.4); }
#play { width: 46px; height: 46px; border-radius: 50%; border: 1px solid rgba(63, 208, 255, 0.55); background: radial-gradient(circle at 50% 35%, rgba(63, 208, 255, 0.3), rgba(63, 208, 255, 0.06)); display: grid; place-items: center; box-shadow: 0 0 22px rgba(63, 208, 255, 0.25); }
#play:hover { box-shadow: 0 0 30px rgba(63, 208, 255, 0.5); }
#play svg { width: 18px; height: 18px; fill: #fff; }
.clock { font-family: var(--mono); display: flex; align-items: baseline; min-width: 128px; }
#clock { font-size: 36px; font-weight: 600; letter-spacing: -0.05em; color: #fff; text-shadow: 0 0 22px rgba(63, 208, 255, 0.5); }
#clockSec { font-size: 17px; color: var(--muted); margin-left: 2px; }
.scrub-wrap { min-width: 0; padding-top: 6px; }
#scrub { position: relative; height: 46px; cursor: ew-resize; border-radius: 6px; outline: none; touch-action: none; }
#scrub:focus-visible { box-shadow: 0 0 0 2px rgba(63, 208, 255, 0.5); }
#scrubCanvas { position: absolute; inset: 0; width: 100%; height: 100%; }
#scrubHead { position: absolute; top: -2px; bottom: 12px; width: 2px; background: #fff; box-shadow: 0 0 12px #fff, 0 0 3px #fff; border-radius: 1px; pointer-events: none; }
#scrubHead::before { content: ""; position: absolute; left: -5px; top: -1px; border: 6px solid transparent; border-top-color: #fff; border-bottom: 0; }
#scrubTip { position: absolute; bottom: calc(100% + 6px); transform: translateX(-50%); padding: 2px 7px; border-radius: 5px; background: var(--panel-solid); border: 1px solid var(--line-strong); font: 11px var(--mono); display: none; pointer-events: none; }
#speeds { display: flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
#speeds button { border: 0; background: transparent; padding: 7px 9px; color: var(--muted); font: 600 11.5px var(--mono); }
#speeds button + button { border-left: 1px solid var(--line); }
#speeds button:hover { color: #fff; }
#speeds button.on { background: rgba(63, 208, 255, 0.2); color: #fff; }

/* ------------------------------------------------------------------ loader */
#loader { position: absolute; inset: 0; z-index: 100; background: #04070d; display: grid; place-content: center; justify-items: center; gap: 18px; transition: opacity 0.7s, visibility 0.7s; }
#loader.done { opacity: 0; visibility: hidden; }
#loader .ring { width: 54px; height: 54px; border-radius: 50%; border: 2px solid rgba(63, 208, 255, 0.2); border-top-color: var(--accent); animation: spin 1s linear infinite; }
#loader p { color: var(--text-2); letter-spacing: 0.1em; text-transform: uppercase; font-size: 11.5px; }
#loader .bar { width: 240px; height: 3px; background: rgba(130, 170, 235, 0.15); border-radius: 2px; overflow: hidden; }
#loader .bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--tgv), var(--ic), var(--ter)); transition: width 0.2s; }

@media (max-width: 1180px) {
  :root { --left: 296px; --right: 340px; }
  .brand p, #modes button b { display: none; }
  .search input { width: 160px; }
}
@media (max-width: 900px) {
  #left { display: none; }
  #speeds, .brand-txt p { display: none; }
  #hint { margin-left: 0; }
}

