    el('span', { class: 'chip', style: { cursor: 'default', border: '0', background: 'none', color: 'var(--muted)' }, text: `${fmtInt(km)} km · ${nStops} stops · avg ${fmtInt(km / (durS / 3600))} km/h` }));
