// ====================================================================== main (left) card
let mainRefs = {};
export function buildMainCard(A) {
  const S = A.S, card = $('cardMain'), D = A.D;
  mainRefs = {};
  const perDay = [0, 0, 0];
  for (const t of D.trips) if (t.o === 0) perDay[t.cat]++;
  A.perDay = perDay;

  const catRows = () => {
    const box = el('div', { class: 'cats' });
