    card.append(el('div', { class: 'stack', id: 'stack', html: CATS.map((c) => `<i style="background:${c.color};flex:1 1 0"></i>`).join('') }));
    card.append(catRows());
    card.append(el('p', { class: 'note', html: '<b>Click</b> a category to show or hide it · <b>Shift-click</b> to isolate · <b>hover</b> to highlight. Click a train or station on the map for its full timetable.' }));
