  for (const s of tr.st) { x0 = Math.min(x0, M.st.x[s]); x1 = Math.max(x1, M.st.x[s]); y0 = Math.min(y0, M.st.y[s]); y1 = Math.max(y1, M.st.y[s]); }
  const pad = Math.max(8000, (x1 - x0 + y1 - y0) * 0.04);
