    else {
      hs = rend.pickStation(mouse.x, mouse.y, S);
      if (hs >= 0) {
        if (S.mode === 'access' && A.router) {
          if (hs !== S.hoverStation) S.journey = A.router.journey(hs);
        } else S.journey = null;
        tip = UI.stationTip(A, hs);
      } else {
