     for (let i = 0; i < t.legs.length; i++) if (t.legs[i] < 0 || t.legs[i] >= M.legsRaw.a.length) badLeg++;
     for (let i = 1; i < t.st.length; i++) if (t.arr[i] < t.dep[i-1] || t.dep[i] < t.arr[i]) nonmono++;
   }
   const prev = new Map();
   for (let h = 0; h < 86400; h += 997) {
